'use strict';
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${ICONS[name] || ICONS.sparkle}"/></svg>`;
const button = (label, action, cls = '', extra = '') => `<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const textButton = (label, action, extra = '') => `<button type="button" class="text" data-action="${action}" ${extra}>${label}</button>`;
const icButton = (name, label, action, extra = '') => `<button type="button" class="icon-btn" aria-label="${esc(label)}" data-action="${action}" ${extra}>${icon(name)}</button>`;
const tag = (label, cls = '') => `<span class="tag ${cls}">${label}</span>`;
const notice = (body, cls = '', name = 'info') => `<div class="notice ${cls}" role="${cls === 'danger' ? 'alert' : 'status'}">${icon(name)}<div>${body}</div></div>`;
const SCREEN_NAMES = {login:'01 · Đăng nhập',consent:'02 · Đồng ý dữ liệu',discover:'03 · Khám phá trong app',understand:'04 · Hiểu chuyến đi',import:'05 · Khớp nơi đã gửi',explore:'06 · Lựa chọn địa điểm',lodging:'07 · Chỗ ở',detail:'08 · Chi tiết & bằng chứng',compare:'09 · So sánh',choices:'10 · Chọn phương án',overview:'11 · Tổng quan lịch trình',day:'12 · Lịch từng ngày',done:'13 · Chốt & phản hồi',today:'14 · Hôm nay / Ở đây',trips:'15 · Chuyến của tôi',saved:'16 · Đã lưu',inbox:'17 · Thông báo',profile:'18 · Hồ sơ & dữ liệu',atlas:'19 · Bản đồ luồng & quyết định',states:'20 · Trạng thái & component',system:'21 · Nền tảng thiết kế'};
const REVIEW_SCENARIOS={login:['normal','error'],consent:['normal'],discover:['normal','empty'],understand:['normal','loading','error','empty','unknown'],import:['normal'],explore:['normal','loading','error','empty','unknown','conflict'],lodging:['normal','loading','empty'],detail:['normal','unknown'],compare:['normal'],choices:['normal','loading','error','overload','unavailable'],overview:['normal'],day:['normal','loading','conflict','unavailable'],done:['normal'],today:['normal','empty','overload','guest'],trips:['normal','loading','empty'],saved:['normal','empty'],inbox:['normal','loading','empty','guest'],profile:['normal','guest'],atlas:['normal'],states:['normal'],system:['normal']};
const FLOW_SCREENS = ['understand','import','explore','lodging','detail','compare','choices','overview','day','done'];
const NAV = [['discover','compass','Khám phá'],['today','sun','Hôm nay'],['trips','suitcase','Chuyến của tôi'],['saved','heart','Đã lưu'],['inbox','bell','Thông báo'],['profile','user','Hồ sơ']];
const initial = () => ({screen:'discover',scenario:'normal',guest:false,date:'2026-10-16',people:2,pace:'Cân bằng',selected:[2,0,5,8,1,6],locked:[1],saved:[0,2],compare:[0,5],group:'all',detailTab:'overview',detailId:0,stay:null,variant:null,day:0,days:[[2,0],[5,8],[1,6]],confirmed:false,feedback:{},feedbackSent:false,checkins:{},skipped:{},ratings:{},calendar:false,read:[],notifies:{morning:true,sunset:true,booking:false},messages:[],question:'pace',understood:true,assistant:false,assistantReply:'',diff:'',undo:null,emptyTrips:false,emptySaved:false,profile:{name:'An',origin:'TP. Hồ Chí Minh',mobility:'Xe máy',companions:'Người yêu'},prefs:['Cà phê','Thiên nhiên'],duration:{},filter:'all'});
let state = initial();
try { const saved = JSON.parse(localStorage.getItem('tg.production.mock.v1')); if (saved) state = {...state,...saved,assistant:false}; } catch {}
let toastTimer, dialogReturn, modalPlace = null, dialogKind = '';
const pOf = id => PLACES.find(p => p.id === Number(id));
const dayDate = offset => {
 if(!state.date)return 'Ngày '+(offset+1);
 const d=new Date(state.date+'T12:00:00+07:00');d.setDate(d.getDate()+offset);
 return d.toLocaleDateString('vi-VN',{day:'numeric',month:'numeric',timeZone:'Asia/Ho_Chi_Minh'});
};
const dateLong = offset => dayDate(offset).replace('/', ' tháng ');
const dateShort = offset => dayDate(offset).replace('/', ' thg ');
const tripRange = () => state.date ? dayDate(0)+'–'+dayDate(state.days.length-1) : 'Chưa chốt ngày';
const price = n => n == null ? 'Chưa có giá' : `${Number(n).toLocaleString('vi-VN')}đ`;
const rating = p => `<div class="rating">${icon('star')}<b>${p.rating.toFixed(1).replace('.',',')}</b><span>(${p.reviewCount.toLocaleString('vi-VN')} đánh giá Maps)</span></div>`;
const brand = () => `<a class="brand" href="#discover"><img src="assets/logo.webp" alt="">TripGuardian</a>`;
const photo = (p, cls = '', extra = '') => `<img src="${p.image}" alt="${esc(p.name)}" class="${cls}" loading="lazy" ${extra}>`;
const hours = p => { const day = p.hours?.fri || Object.values(p.hours || {})[0]; return day?.length ? day.map(x => x.join('–')).join(', ') : 'Chưa có thông tin'; };
const heading = (kicker,title,body='',actions='') => `<header class="page-heading"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1>${body ? `<p>${body}</p>` : ''}</div>${actions}</header>`;
const save = () => { try { localStorage.setItem('tg.production.mock.v1',JSON.stringify(state)); } catch {} };
function toast(message) { $('#toast').textContent = message; $('#toast').classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(() => $('#toast').classList.remove('show'),3200); }
function remember() { state.undo = JSON.parse(JSON.stringify({selected:state.selected,locked:state.locked,days:state.days,duration:state.duration,stay:state.stay,variant:state.variant})); }
function go(screen, resetScenario = true) { if (!SCREEN_NAMES[screen]) screen = 'discover'; closeDialog(); if (resetScenario) state.scenario = 'normal'; state.screen = screen; state.assistant = false; location.hash = screen; render(); window.scrollTo(0,0); }
function guestNotice() { return state.guest ? notice(`<b>Bạn đang dùng với tư cách khách.</b> Chuyến sẽ bị xóa sau 24 giờ không hoạt động. ${textButton('Đăng nhập để lưu','google')}`,'warn') : ''; }
function flowHeader() {
 const current = ['understand','import'].includes(state.screen) ? 0 : ['explore','lodging','detail','compare'].includes(state.screen) ? 1 : state.screen === 'done' ? 3 : 2;
 const steps = [['understand','Tìm hiểu'],['explore','Lựa chọn'],['choices','Lịch trình'],['done','Đánh giá']];
 return `<header class="app-header">${brand()}<nav class="stepper" aria-label="Tiến trình chuyến đi">${steps.map(([id,label],i) => `${i ? '<span class="connector" aria-hidden="true"></span>' : ''}<button class="step ${i===current ? 'current' : i<current ? 'done' : ''}" data-nav="${id}" ${i===current ? 'aria-current="step"' : ''}><i>${i<current ? icon('check') : i+1}</i>${label}</button>`).join('')}</nav><div class="row">${button(`${icon('calendar')}<span>Tóm tắt chuyến đi</span>`,'summary','summary-btn')}<button class="avatar" aria-label="Hồ sơ của bạn" data-nav="profile">AN</button></div></header>`;
}
function sidebar() { return `<aside class="sidebar">${brand()}<span class="eyebrow" style="margin-left:16px;color:var(--faint)">Chuyến đi của bạn</span><nav aria-label="Điều hướng chính">${NAV.filter(([id]) => !state.guest || !['today','inbox'].includes(id)).map(([id,ic,label]) => `<a class="navlink ${id===state.screen ? 'on' : ''}" href="#${id}" ${id===state.screen ? 'aria-current="page"' : ''}>${icon(ic)}${label}${id==='saved' && state.saved.length ? `<small>${state.saved.length}</small>` : ''}</a>`).join('')}</nav><div style="margin-top:28px">${button(`${icon('plus')} Chuyến mới`,'new-trip','soft','style="width:100%"')}</div><div class="footer"><button class="avatar" data-nav="profile" aria-label="Hồ sơ">AN</button><div><b style="font-size:13px">${state.guest ? 'Khách' : esc(state.profile.name)}</b><p style="font-size:11px">${state.guest ? 'Chưa lưu tài khoản' : 'Chuyến này theo gu bạn'}</p></div></div></aside>`; }
function reviewbar() {
 const scenarios = REVIEW_SCENARIOS[state.screen] || ['normal'];
 const labels = {normal:'Bình thường',loading:'Đang tải',error:'Lỗi kết nối',empty:'Trống / không khớp',unknown:'Thiếu thông tin',conflict:'Xung đột giới hạn',overload:'Quá tải lịch',unavailable:'Không khả dụng',guest:'Dùng với khách'};
 $('#review').innerHTML = `<div class="reviewbar"><div class="row intro"><span class="dot"></span><b>PRODUCTION UI MOCK</b><span>Desktop · Nội dung chuyến đi minh họa</span></div><div class="row"><label for="screen-picker"><span class="review-label">Màn</span><select id="screen-picker">${Object.entries(SCREEN_NAMES).map(([k,v]) => `<option value="${k}" ${state.screen===k ? 'selected' : ''}>${v}</option>`).join('')}</select></label><label for="scenario-picker">Trạng thái<select id="scenario-picker">${scenarios.map(k => `<option value="${k}" ${state.scenario===k ? 'selected' : ''}>${labels[k]}</option>`).join('')}</select></label><button class="review-notes" data-nav="atlas">Quyết định thiết kế</button><button data-action="reset">Đặt lại</button></div></div>`;
}
function deviceGate() { return `<section class="device-gate"><img src="assets/logo.webp" alt="TripGuardian"><span class="eyebrow">Bề mặt hiện tại · Desktop</span><h1>Một chuyến đi<br>cần chút không gian.</h1><p>Production hiện tại dùng trên máy tính. Mở mock ở màn hình từ 1024 px để đi thử đầy đủ các bước.</p><p>Trên điện thoại, production hiển thị trang Dùng ứng dụng. Ứng dụng điện thoại chưa có bản phát hành.</p>${button('Xem phạm vi & quyết định','design-mobile','soft')}</section>`; }
function render() {
 state.day=Math.max(0,Math.min(state.day,state.days.length-1));
 reviewbar();
 const screen = state.screen;
 const content = SCREENS[screen] ? SCREENS[screen]() : discover();
 const isFlow = FLOW_SCREENS.includes(screen);
 const isAuth = ['login','consent'].includes(screen);
 const inside = isAuth ? content : isFlow ? flowHeader()+`<main id="main" tabindex="-1">${content}</main>` : sidebar()+`<div class="main-shell"><header class="outside-header"><span>${['atlas','states','system'].includes(screen) ? 'Thiết kế cho production' : 'Đà Lạt · Chuyến đi của bạn'}</span><div class="row">${tag(state.guest ? 'Khách' : 'Theo lời bạn · sửa được','neutral')}${state.guest?'':icButton('bell','Mở thông báo','nav-inbox')}<button class="avatar" data-nav="profile" aria-label="Hồ sơ">AN</button></div></header><main id="main" tabindex="-1">${content}</main></div>`;
 $('#app').innerHTML = `<div class="desktop-ui">${inside}</div>${deviceGate()}`;
 document.title = `${SCREEN_NAMES[screen].split(' · ')[1]} · TripGuardian mock`;
 updateMaps();
 save();
}
function empty(title,body,action,label) { return `<section class="empty"><svg class="art" viewBox="0 0 110 80" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path stroke-dasharray="5 5" d="M6 64C34 64 21 20 50 38S80 68 103 22"/><path d="M71 9a12 12 0 1 0-24 0c0 12 12 23 12 23S71 21 71 9Z"/><circle cx="7" cy="64" r="4"/><circle cx="103" cy="22" r="4"/></svg><h2>${title}</h2><p>${body}</p>${button(`${label} ${icon('arrow')}`,action,'primary')}</section>`; }
function loadingCards(n=3) { return `<div class="grid3" aria-busy="true" aria-label="Đang tải">${Array.from({length:n},() => `<div class="panel" style="overflow:hidden"><div class="skeleton photo"></div><div class="panel pad"><div class="skeleton line"></div><div class="skeleton line short"></div><div class="skeleton line"></div></div></div>`).join('')}</div>`; }
function auth(consent=false) { return `<main id="main" class="auth" tabindex="-1"><aside class="auth-art">${brand()}<div><span class="eyebrow" style="color:#dce8df">ĐÀ LẠT · THEO CÁCH CỦA BẠN</span><h1>Đà Lạt có cả nghìn chỗ đẹp.<br><em>Chuyến này cần mấy chỗ?</em></h1><p>Bạn chọn nơi. Mình giúp hiểu chuyến, cân nhắc đánh đổi và xếp lịch.</p></div><small style="color:#dce8df">TripGuardian · Mỗi gợi ý có lý do</small></aside><section class="auth-form"><div class="auth-card">${consent ? `<span class="eyebrow">Trước khi bắt đầu</span><h1>Bạn và dữ liệu<br>của bạn.</h1><p>Mấy điều cần biết trước khi lưu chuyến:</p><ul><li>Tên, email và ảnh từ Google dùng để đăng nhập và hiện hồ sơ.</li><li>Chuyến đi, lời bạn nhắn và thao tác được lưu; quản trị viên xem được để cải thiện gợi ý.</li><li>Hồ sơ là gợi ý ban đầu. Điều bạn nói cho chuyến này luôn thắng.</li><li>Không thu GPS. Google Calendar chỉ ghi khi bạn xác nhận.</li><li>Bạn có thể xóa tài khoản trong Hồ sơ.</li></ul><label class="check-label"><input id="consent-check" type="checkbox"><span>Tôi đồng ý với Điều khoản sử dụng và Chính sách dữ liệu.</span></label>${button(`Bắt đầu ${icon('arrow')}`,'accept','primary','id="consent-submit" disabled')}${textButton('Dùng tài khoản khác','nav-login')}` : `<span class="eyebrow">Bắt đầu từ một câu</span><h1>Chuyến Đà Lạt<br>của bạn.</h1><p>Kể điều bạn muốn. Mình giúp tìm nơi phù hợp và xem cả chuyến có đi được cùng nhau không.</p>${state.scenario==='error' ? notice('Phiên đăng nhập đã hết hạn. Bấm lại nút bên dưới nhé.','danger') : ''}${button(`Tiếp tục với Google ${icon('arrow')}`,'google','primary')}${button('Dùng thử, không cần tài khoản','guest')}<p class="fine">${icon('shield')} Có tài khoản: mở chuyến trên mọi máy.<br>Khách: chuyến bị xóa sau 24 giờ không hoạt động.</p><small>Đăng nhập trong mock chỉ mô phỏng chuyển màn.</small>`}</div></section></main>`; }
function discover() { return `<div class="content">${guestNotice()}<section class="discover-hero"><div><span class="eyebrow">Ít tìm kiếm hơn · Nhiều trải nghiệm hơn</span><h1>Đà Lạt,<br><em>đúng gu của bạn.</em></h1><p>Một buổi săn mây, một quán cà phê, một khoảng nghỉ. Kể chuyến bạn muốn, mình giúp ghép những nơi hợp nhau.</p><form class="start-form" data-form="start"><label class="sr" for="start-text">Kể chuyến đi bạn muốn</label><textarea id="start-text" placeholder="3 ngày cho hai người, đi xe máy, thích cà phê và săn mây…"></textarea><div class="between"><small>${icon('sparkle')} Gõ một câu, hoặc dán danh sách đã lưu</small><button class="btn primary" type="submit">Bắt đầu ${icon('arrow')}</button></div></form><div class="row">${['3 ngày','Đi với người yêu','Cà phê','Săn mây'].map(c => `<button class="chip" data-start-chip="${c}">${c}</button>`).join('')}</div></div><div class="hero-photo">${photo(PLACES[2])}<span class="photo-caption">Săn mây Cầu Đất · Ảnh Google Maps</span></div></section>${state.scenario!=='empty' ? `<section class="panel active-trip">${photo(PLACES[0])}<div class="body"><span class="eyebrow" style="margin-bottom:6px">Chuyến đang lập</span><h3>Cuối tuần, lên Đà Lạt</h3><p class="small">${tripRange()} · ${state.people} người · ${state.selected.length} nơi đã chọn</p></div>${button(`Đi tiếp ${icon('arrow')}`,'resume','soft')}</section>` : ''}<div class="between section-title"><h2>Một chút cảm hứng để bắt đầu</h2><small>Mỗi chủ đề mở một chuyến mới</small></div><div class="grid3">${[[2,'Theo giờ','Săn mây, đón một ngày mới'],[0,'Theo gu','Cà phê và một góc bình yên'],[1,'Theo khu','Chiều muộn, hẹn nhau bên hồ']].map(([id,sub,title])=>`<button class="theme" data-theme="${id}">${photo(PLACES[id])}<span class="body"><small>${sub}</small><h3>${title}</h3><small>Bắt đầu từ chủ đề này</small></span><span class="go">${icon('arrow')}</span></button>`).join('')}</div></div>`; }
function rowPlace(p, preview=false) { return `<article class="place-row"><button class="photo-button" data-detail="${p.id}" aria-label="Chi tiết ${esc(p.name)}">${photo(p)}</button><div class="body"><span class="meta">${p.kind} · ${p.area}</span><h3>${p.short}</h3>${rating(p)}<p>${icon('calendar')} ${hours(p)} · theo catalog</p><p style="color:var(--pine)">${icon('check')} ${p.id===0 || p.id===5 ? 'Cà phê — đúng loại nơi bạn muốn ghé' : 'Thiên nhiên — theo mong muốn chuyến này'}</p><p>Điều kiện đi lại và độ đông: cần kiểm tra thêm.</p>${textButton(`Xem chi tiết ${icon('arrow')}`,'detail-'+p.id)}</div><button class="icon-btn heart ${state.saved.includes(p.id)?'on':''}" data-save="${p.id}" aria-pressed="${state.saved.includes(p.id)}" aria-label="${state.saved.includes(p.id)?'Bỏ lưu':'Lưu'} ${esc(p.short)}">${icon('heart')}</button></article>`; }
function questionMarkup() {
 if (!state.understood) return `<div class="question"><span class="eyebrow">Bắt đầu tự nhiên thôi</span><h2>Chuyến bạn đang mong là chuyến như thế nào?</h2><p>Kể đi cùng ai, mấy ngày, muốn sống chậm hay ăn cho đã. Gửi ảnh hoặc danh sách một nơi bạn thích cũng được.</p><div class="row" style="margin-top:18px">${button('Mình có nơi đã lưu','nav-import','soft')}${button('Chưa biết đi đâu','first-story')}</div></div>`;
 if (state.question==='dates') return `<div class="question"><span class="eyebrow">Để xem đúng ngày bạn đi</span><h2>Bạn đi từ ngày nào?</h2><p>Chưa chốt ngày cũng được. Những thông tin phụ thuộc ngày sẽ giữ là chưa rõ.</p><form data-form="dates" style="margin-top:18px"><label>Ngày bắt đầu<input type="date" name="date" value="${state.date}" required></label><div class="row" style="margin-top:16px"><button class="btn primary" type="submit">Lưu ngày đi</button>${textButton('Mình chưa chắc','skip-date')}</div></form></div>`;
 if (state.question==='logistics') return `<div class="question"><span class="eyebrow">Hậu cần chuyến đi</span><h2>Mình hỏi nốt chuyện đi lại.</h2><p>Không chọn vé hay đặt phòng ở đây. Chỗ ở có thể chọn sau, theo các nơi muốn ghé.</p><form data-form="logistics" class="stack" style="margin-top:18px"><label>Điểm xuất phát<input name="origin" value="TP. Hồ Chí Minh"></label><label>Cách tới Đà Lạt<select name="transport"><option>Tự đi</option><option>Xe khách</option><option>Máy bay</option></select></label><label>Chỗ ở<input name="stay" placeholder="Tên chỗ đã đặt, hoặc để trống nếu chưa có"></label><div class="row"><button type="submit" class="btn primary">Xong phần này</button>${textButton('Bỏ qua, gợi ý trước','finish-questions')}</div></form></div>`;
 if (state.question==='finished') return `<div class="question"><span class="eyebrow">Đã đủ để xem trước</span><h2>Một chuyến cân bằng, theo cách của hai bạn.</h2><p>Mình đã ghi nhận ngày đi, người đi cùng và nhịp đi. Các nơi bên phải mới là bản xem trước; bạn chọn ở bước tiếp theo.</p><div class="row" style="margin-top:18px">${button('Kiểm tra tóm tắt chuyến đi','summary','soft')}${textButton('Mình có nơi muốn ghé','nav-import')}</div></div>`;
 return `<div class="question"><span class="eyebrow">Thêm một chút về chuyến này</span><h2>Bạn muốn một ngày trôi qua thế nào?</h2><p>Nhịp đi giúp mình hiểu bạn muốn dành bao lâu ở mỗi nơi.</p><div class="pace-grid">${[['Thong thả',0,'Ít nơi, ở lại lâu hơn'],['Cân bằng','pace','Có đi chơi, có nghỉ chân'],['Đi nhiều',2,'Muốn trải nghiệm nhiều hơn']].map(([label,img,sub])=>`<button class="pace ${state.pace===label?'on':''}" data-pace="${label}" aria-pressed="${state.pace===label}"><img src="${img==='pace' ? 'assets/pace.webp' : PLACES[img].image}" alt=""><b>${label}</b><small>${sub}</small><i class="radio" aria-hidden="true"></i></button>`).join('')}</div><div class="between">${textButton('Chưa chắc, xem trước đã','skip-pace')}<small>Có thể đổi bất cứ lúc nào</small></div></div>`;
}
function understand() {
 if(state.scenario==='error') return `<div class="content narrow">${empty('Chưa kết nối được trợ lý','Những gì bạn đã kể vẫn còn. Thử lại sau ít phút.','retry','Thử lại')}</div>`;
 return `<section class="workspace"><section class="panel chat-panel" aria-label="Trò chuyện hiểu chuyến đi"><div class="panel-heading"><span>${state.understood ? `${state.days.length} ngày · ${state.people} người · ${state.mobility||'Xe máy'}` : 'Chuyến Đà Lạt của bạn'}</span>${textButton(`${icon('edit')} Sửa`,'summary')}</div><div class="chat-log" id="chat-log">${state.understood ? `<div class="message user">${esc(state.story || 'Đà Lạt 3 ngày 2 đêm, đi cùng người yêu. Tụi mình đi xe máy, thích cà phê và thiên nhiên.')}</div><div class="message bot"><div class="byline"><span class="bot-mark">${icon('sparkle')}</span>TripGuardian <small>Hiểu theo lời bạn</small></div><p>Một chuyến cho hai người, có cà phê và khoảng trời xanh. Mình đã ghi lại rồi. Chưa chắc điều gì thì bạn cứ sửa nhé.</p></div>` : ''}${state.scenario==='loading' ? `<div aria-busy="true"><p class="small">${icon('sparkle')} Đang đọc những điều bạn vừa kể…</p><div class="skeleton line"></div><div class="skeleton line short"></div></div>` : questionMarkup()}${state.messages.map(m=>`<div class="message user">${esc(m)}</div><div class="message bot"><div class="byline"><span class="bot-mark">${icon('sparkle')}</span>TripGuardian</div><p>Mình đã giữ lời bạn trong ghi chú chuyến đi. Bạn có thể kiểm tra lại ở Tóm tắt chuyến đi.</p></div>`).join('')}${state.scenario==='unknown' ? notice('Ngày đi và chỗ ở chưa rõ. Mình vẫn gợi ý trước; thông tin phụ thuộc các phần này chưa thể xác nhận.','warn') : ''}</div><form class="composer" data-form="chat"><label class="sr" for="chat-text">Kể thêm về chuyến đi</label><textarea id="chat-text" placeholder="Kể thêm, hoặc dán link một nơi bạn thích…" maxlength="1000"></textarea><div class="between"><div class="row"><label class="text" style="font-size:12px;cursor:pointer" for="chat-image">${icon('clip')} Ảnh, link, ghi chú</label><input type="file" id="chat-image" accept="image/*" hidden>${textButton('Có nơi đã lưu','nav-import')}</div><button class="icon-btn" type="submit" aria-label="Gửi tin nhắn">${icon('arrow')}</button></div></form></section><aside class="panel suggest-panel" aria-label="Nơi đang hợp với bạn"><div class="suggest-head"><span class="eyebrow">Đà Lạt · Xem trước</span><h2>Những nơi đang hợp.</h2><p>Bấm xem chi tiết. Bạn chọn nơi ở bước tiếp theo.</p><div class="between" style="margin-top:14px"><span class="match-count"><b>${state.understood ? '167' : '1.773'}</b> nơi${state.understood ? ' đang hợp' : ''}</span>${tag('Kịch bản minh họa','neutral')}</div><div class="tabs" role="tablist" aria-label="Nhóm xem trước" style="margin-top:12px">${[['all','Tất cả'],['food','Cà phê'],['sight','Thiên nhiên']].map(([g,l])=>`<button role="tab" aria-selected="${state.group===g}" data-group="${g}">${l}</button>`).join('')}</div></div><div class="suggest-list">${state.scenario==='loading' ? loadingCards(1) : state.scenario==='empty' ? `<div class="empty" style="margin:16px auto;padding:20px"><h2>Chưa có nơi hợp.</h2><p>Thử đổi một mong muốn trong Tóm tắt chuyến đi.</p>${button('Xem mong muốn','summary','soft')}</div>` : [PLACES[0],PLACES[1],PLACES[2],PLACES[5]].filter(p=>state.group==='all'||p.group===state.group).map(p=>rowPlace(p,true)).join('')}</div><footer class="suggest-foot"><p><b>Khi bạn muốn đi tiếp</b><br>Bạn sẽ chọn nơi ở bước tiếp theo.</p>${button(`Tiếp tục đến chọn nơi ${icon('arrow')}`,'to-selection','primary',state.scenario==='loading'?'disabled':'')}</footer></aside></section>`;
}
function imported() { return `<div class="content narrow">${heading('Từ danh sách bạn gửi','Mình khớp từng nơi, bạn kiểm tra.','Không đoán tên gần giống. Nơi chưa khớp được giữ riêng, chưa đưa vào lịch.')}<div class="panel pad import-list"><span class="small">3 mục từ ghi chú chuyến đi · 1 tên trùng đã gộp</span><div class="import-item">${photo(PLACES[5])}<div style="flex:1"><h3>Túi Mơ To / Tiệm Túi Mơ To</h3><p class="small">Đã khớp với Tiệm Cà Phê Túi Mơ To</p></div>${tag(`${icon('check')} Đã khớp`)}</div><div class="import-item">${photo(PLACES[0])}<div style="flex:1"><h3>“Quán cà phê trên đồi”</h3><p class="small">Có phải Thênh Thang, Trại Mát?</p></div>${button('Đúng nơi này','match-import','soft','id="match-import"')}</div><div class="import-item"><span class="icon-btn">${icon('pin')}</span><div style="flex:1"><h3>Link bạn gửi</h3><p class="small">Chưa tìm được địa điểm tương ứng.</p></div>${tag('Chưa xác minh','warn')}</div><div class="row" style="margin-top:18px">${button('Giữ mục chưa xác minh','keep-import','soft')}${textButton('Bỏ mục này','remove-import')}</div></div><div class="panel pad" style="margin-top:24px"><h3>Ý nghĩa các nơi bạn gửi</h3><p class="small" style="margin:10px 0 18px">Đã lưu và bắt buộc đến là hai điều khác nhau. “Đã đi rồi” không có nghĩa là bạn thích nơi đó.</p><div class="row">${['Muốn ghé','Bắt buộc đến','Đã đi rồi','Tránh lần này','Chưa rõ'].map(l=>`<button class="chip" data-import-intent="${l}" aria-pressed="false">${l}</button>`).join('')}</div></div><div class="row" style="margin-top:24px">${button(`Tiếp tục hiểu chuyến ${icon('arrow')}`,'nav-understand','primary')}${button('Xem nơi gợi ý','to-selection')}</div></div>`; }
const reasons = {0:'Cà phê Trại Mát — theo loại nơi bạn muốn ghé.',1:'Dạo hồ — có khoảng nghỉ trong chuyến.',2:'Săn mây — đúng mong muốn buổi sáng.',3:'Thác và hoạt động ngoài trời — thêm trải nghiệm.',4:'Khám phá núi — theo gu thiên nhiên.',5:'Cà phê — gần cụm Trại Mát của chuyến.',6:'Mua sắm, đặc sản — dành khoảng cuối ngày.',7:'Kiến trúc — một lựa chọn để cân nhắc.',8:'Văn hóa, thiên nhiên — thêm một nhịp chậm.'};
function cardPlace(p,savedMode=false) {
 const chosen = state.selected.includes(p.id), locked = state.locked.includes(p.id);
 return `<article class="place-card ${chosen?'selected':''}"><button class="photo" data-detail="${p.id}" aria-label="Chi tiết ${esc(p.name)}">${photo(p)}<span class="credit">Ảnh Google Maps</span></button><button class="icon-btn heart ${state.saved.includes(p.id)?'on':''}" data-save="${p.id}" aria-label="${state.saved.includes(p.id)?'Bỏ lưu':'Lưu'} ${esc(p.short)}" aria-pressed="${state.saved.includes(p.id)}">${icon('heart')}</button><div class="body"><span class="category">${p.kind} · ${p.area}</span><h3>${p.short}</h3>${rating(p)}<p class="reason">${icon('check')} ${reasons[p.id]}</p><p class="trade">${icon('info')} ${p.id===2 ? 'Cần đi sớm; việc thấy mây phụ thuộc thời tiết.' : 'Giá và điều kiện của chuyến cần kiểm tra thêm.'}</p><div class="metrics"><span>${icon('clock')} ≈${p.duration} phút</span>${tag('Chưa đánh giá điều kiện','neutral')}</div><div class="actions">${button(`${icon(chosen?'check':'plus')} ${chosen?'Đã chọn':'Thêm vào chuyến'}`,'select-'+p.id,chosen?'soft':'primary',locked?'disabled':'')}${icButton(locked?'lock':'unlock',locked?'Bỏ khóa '+p.short:'Khóa '+p.short,'lock-'+p.id,`aria-pressed="${locked}"`)}${icButton('arrow','Chi tiết '+p.short,'detail-'+p.id)}</div>${!savedMode ? `<label class="compare"><input type="checkbox" data-compare="${p.id}" ${state.compare.includes(p.id)?'checked':''}>So sánh nơi này</label>` : '<p class="small" style="margin-top:14px">Chỉ thêm nếu nằm trong gợi ý của chuyến hiện tại.</p>'}</div></article>`;
}
function selectedBar() { const conflict = state.scenario==='conflict';return `<footer class="sticky-bottom"><div class="row"><button class="selected-link" data-action="selected"><span class="selected-thumbs">${state.selected.slice(0,3).map(id=>photo(pOf(id))).join('')}</span><div><b>${state.selected.length} nơi đã chọn ${icon('chevronDown')}</b><p>${state.diff || (conflict ? 'Có một chặng vượt giới hạn của bạn' : 'Ước tính cho kịch bản · chưa phải lịch xác nhận')}</p></div></button>${state.diff&&state.undo ? textButton('Hoàn tác','undo') : ''}</div><div class="metrics">${state.compare.length>=2 ? button(`So sánh ${state.compare.length} nơi`,'nav-compare') : ''}<span class="small">${state.stay===null?'Chưa chọn chỗ ở':esc(STAYS[state.stay]?.name||'Chỗ ở đã cung cấp')}</span>${conflict ? button('Xem cách sửa','conflicts','soft') : ''}${button(`Xem lịch trình ${icon('arrow')}`,'to-choices','primary',!state.selected.length||conflict?'disabled':'')}</div></footer>`; }
function catalogTabs() { return `<div class="tabs" role="tablist" aria-label="Nhóm địa điểm">${[['all','Tất cả'],['sight','Tham quan & thiên nhiên'],['food','Ăn uống & cà phê'],['shop','Mua sắm'],['lodging',state.stay===null?'Chỗ ở · cần chọn':'Chỗ ở · đã chọn']].map(([id,label])=>`<button role="tab" aria-selected="${state.screen==='lodging'?id==='lodging':state.group===id}" data-catalog="${id}">${id==='lodging'?icon('bed'):''} ${label}</button>`).join('')}</div>`; }
function explore() {
 let body = state.scenario==='loading' ? loadingCards(6) : state.scenario==='error' ? empty('Chưa tải được danh sách','Những nơi bạn đã chọn vẫn còn.','retry','Thử lại') : state.scenario==='empty' ? empty('Chưa có nơi vượt qua giới hạn','Thiếu bằng chứng không chứng minh một nơi đáp ứng yêu cầu. Xem lại giới hạn hoặc giữ để kiểm tra sau.','summary','Xem giới hạn của tôi') : `<div class="catalog-grid">${PLACES.filter(p=>state.group==='all'||p.group===state.group).map(p=>cardPlace(p)).join('')}</div>`;
 return `<div class="content">${heading('Bước 2 · Lựa chọn','Chọn những nơi bạn thật sự muốn ghé.','Vì sao hợp, đánh đổi gì — nhìn ngay trên thẻ. Thêm một nơi chưa có nghĩa là phải đi hết.',button(`${icon('sliders')} Mong muốn chuyến này`,'summary'))}${guestNotice()}<div class="selection-summary">${tag(`${state.days.length} ngày · ${state.people} người · ${state.mobility||'Xe máy'}`,'neutral')}${tag(state.prefs.join(' · ')||'Chưa có gu cụ thể')}${state.maxLeg?`<span class="chip hard">${icon('lock')} Mỗi chặng ≤${state.maxLeg} phút</span>`:''}${state.locked.map(id=>tag(`${icon('lock')} Giữ ${pOf(id).short}`)).join('')}<button class="chip prior" data-action="summary">Ít đông · từ hồ sơ, sửa được</button></div><div class="between catalog-head">${catalogTabs()}<small>Gợi ý theo chuyến đi hiện tại</small></div>${state.scenario==='conflict'?notice(`<b>Săn mây Cầu Đất: chặng ≈42 phút vượt giới hạn 30 phút.</b><br>${textButton('Xem các cách sửa và cái giá','conflicts')}`,'warn','warn'):''}${state.scenario==='unknown'?notice('Chưa xác minh được điều kiện tiếp cận cho một số nơi. Nơi thiếu bằng chứng không được coi là đáp ứng giới hạn cứng.','warn'):''}<div style="margin-top:24px">${body}</div>${state.scenario==='normal'?`<div class="panel pad" style="margin-top:26px"><details><summary class="small">Các nơi bị giới hạn loại · xem lý do</summary><p class="small" style="margin-top:12px">Thiết kế giữ cách production giải thích theo từng giới hạn. ${textButton('Sửa giới hạn ở vé chuyến','summary')}</p></details></div>`:''}</div>${selectedBar()}${state.assistant?assistant():`<button class="float-assistant" data-action="assistant">${icon('sparkle')} Hỏi TripGuardian</button>`}`;
}
function assistant() { return `<aside class="panel assistant-panel" aria-label="Hỏi TripGuardian"><div class="panel-heading"><b>${icon('sparkle')} Hỏi TripGuardian</b>${icButton('x','Đóng trợ lý','assistant')}</div><div class="body"><span class="eyebrow">Dựa trên chuyến này</span><p>Muốn thêm cà phê, bớt đi xa, hoặc hỏi vì sao một nơi không được gợi ý?</p><div class="row" style="margin-top:20px">${button('Vì sao không gợi ý Langbiang?','why-not','soft')}</div>${state.assistantReply?`<div class="notice" style="margin-top:22px">${esc(state.assistantReply)}</div>`:''}</div><form data-form="assistant"><label for="assistant-text">Nhắn cho TripGuardian</label><textarea id="assistant-text" placeholder="Mình muốn ít di chuyển hơn…"></textarea><button type="submit" class="btn primary" style="width:100%;margin-top:12px">Gửi ${icon('arrow')}</button><small>Mock mô phỏng hội thoại; không gọi model.</small></form></aside>`; }
function lodging() { return `<div class="content">${heading('Bước 2 · Chỗ ở','Mỗi ngày bắt đầu và kết thúc ở đây.','Gợi ý chỗ ở quanh nơi đã chọn. Hợp gu trước, gần sau; cả chuyến chỉ có một chỗ ở.')}${catalogTabs()}${state.stay!==null ? `<div style="margin-top:24px">${notice(`<b>Bạn ở ${esc(STAYS[state.stay]?.name || 'Chỗ ở đã cung cấp')}.</b><br>Mọi ngày bắt đầu và kết thúc ở đây. ${textButton('Bỏ chỗ này','clear-stay')}`)}</div>` : `<div style="margin-top:24px">${notice('Chưa chọn chỗ ở. Bạn vẫn xem lịch được; đường đi mỗi sáng và tối chưa thể tính đủ.','warn','bed')}</div>`}<div style="margin-top:26px">${state.scenario==='loading' ? loadingCards() : state.scenario==='empty' ? empty('Chọn vài nơi muốn đi trước','Chỗ ở được gợi ý quanh các nơi bạn muốn ghé.','nav-explore','Chọn địa điểm') : `<div class="grid3">${STAYS.map((s,i)=>`<article class="panel lodging-card"><div class="lodging-art">${s.image?photo(s):icon('bed')}<small>Chưa có ảnh được xác minh cho chỗ ở này</small></div>${tag('Nguồn Google Maps','neutral')}<h3>${esc(s.name)}</h3>${rating(s)}<p>Độ phù hợp theo gu: <b>chưa có bằng chứng đủ trong mock.</b></p><p>Thời gian đến các nơi đã chọn: <b>cần tính theo lịch.</b></p><div class="price mono">${price(s.price)}<small>/đêm</small></div><small>Giá tham khảo Maps ngày ${esc(s.asOf)} · kiểm lại khi đặt.</small>${button(state.stay===i?`${icon('check')} Đang ở đây`:'Ở đây','stay-'+i,state.stay===i?'soft':'primary',state.stay===i?'disabled':'')}</article>`).join('')}</div>`}</div><section class="panel pad" style="margin-top:28px;max-width:700px"><h3>Tìm chỗ ở khác / đã có booking</h3><p class="small" style="margin:10px 0 18px">Chọn đúng tên và địa chỉ. Không đoán khớp khi chỉ có tên gần giống.</p><form data-form="stay-search"><label>Tên chỗ ở<input name="query" list="stay-names" placeholder="Gõ tên khách sạn hoặc homestay"><datalist id="stay-names">${STAYS.map(s=>`<option value="${esc(s.name)}">`).join('')}</datalist></label><div class="row" style="margin-top:14px"><button type="submit" class="btn soft">Kiểm tra tên</button>${textButton('Chưa có, chọn sau','nav-explore')}</div></form></section></div>${selectedBar()}`; }
function compare() { const ps=state.compare.slice(0,3).map(pOf).filter(Boolean); return `<div class="content">${heading('Cân nhắc trước khi chọn','Chỗ nào hợp chuyến này hơn?','Chỉ đặt cạnh nhau những điều khác biệt. Bạn chọn, mình không chọn thay.',button(`${icon('arrowLeft')} Về lựa chọn`,'nav-explore'))}${ps.length<2 ? empty('Chọn ít nhất hai nơi','Đánh dấu So sánh trên các thẻ địa điểm.','nav-explore','Về danh sách') : `<div class="panel" style="overflow:auto"><table class="compare-table"><thead><tr><th>Đang so sánh</th>${ps.map(p=>`<td>${photo(p,'cover')}<h3>${p.short}</h3>${rating(p)}</td>`).join('')}</tr></thead><tbody><tr><th>Trải nghiệm</th>${ps.map(p=>`<td>${p.kind}<br><small>${reasons[p.id]}</small></td>`).join('')}</tr><tr><th>Khu vực</th>${ps.map(p=>`<td>${p.area}</td>`).join('')}</tr><tr><th>Thời gian dự kiến</th>${ps.map(p=>`<td class="mono">≈${p.duration} phút</td>`).join('')}</tr><tr><th>Giá, độ đông</th>${ps.map(()=>`<td>Chưa có thông tin đủ<br>${tag('Chưa xác nhận','warn')}</td>`).join('')}</tr><tr><th>Đánh đổi</th>${ps.map(p=>`<td>${p.id===2?'Cần đi sớm, phụ thuộc thời tiết.':'Cần kiểm tra giờ ghé và chi phí trong lịch.'}</td>`).join('')}</tr><tr><th>Lựa chọn của bạn</th>${ps.map(p=>`<td>${button(state.selected.includes(p.id)?'Đã chọn':'Thêm vào chuyến','select-'+p.id,state.selected.includes(p.id)?'soft':'primary')}${textButton('Xem bằng chứng','detail-'+p.id)}</td>`).join('')}</tr></tbody></table></div>`}<section class="panel pad" style="margin-top:28px"><h3>Bạn ưu tiên trải nghiệm nào hơn?</h3><div class="row" style="margin-top:15px">${button('Ngồi cà phê lâu hơn','prefer-coffee','soft')}${button('Thêm một nơi thiên nhiên','prefer-nature')}${textButton('Chưa chắc, giữ cả hai để cân nhắc','nav-explore')}</div></section></div>${selectedBar()}`; }
function detailContent(p, modal=false) { const tab=state.detailTab;return `<div class="detail-hero"><div><span class="eyebrow">${p.kind} · ${p.area}</span><h1>${p.name}</h1><p>${p.id===0?'Cà phê Trại Mát, để bạn cân nhắc cho một khoảng nghỉ.':p.kind+' — xem thông tin trước khi quyết định ghé.'}</p><div class="facts"><div><small>Đánh giá trên Maps</small><b>${p.rating.toFixed(1).replace('.',',')} · ${p.reviewCount.toLocaleString('vi-VN')} lượt</b></div><div><small>Thời gian dự kiến</small><b class="mono">≈${p.duration} phút</b></div></div><div class="row">${button(state.selected.includes(p.id)?`${icon('check')} Đã chọn`:`Thêm vào chuyến ${icon('arrow')}`,'select-'+p.id,state.selected.includes(p.id)?'soft':'primary',state.screen==='understand'?'disabled':'')}${icButton('heart','Lưu '+p.short,'save-'+p.id,`aria-pressed="${state.saved.includes(p.id)}"`)}${icButton('lock','Khóa '+p.short,'lock-'+p.id,`aria-pressed="${state.locked.includes(p.id)}"`)}</div>${state.screen==='understand'?'<p class="small" style="margin-top:12px">Bạn chọn nơi ở bước Lựa chọn; hiện chỉ xem trước.</p>':''}</div><div class="gallery ${p.gallery.length===1?'single':''}"><button data-image="${p.image}" aria-label="Xem ảnh lớn ${esc(p.short)}">${photo(p)}<span class="credit">Ảnh Google Maps · ${p.gallery.length} ảnh</span></button>${p.gallery.length>1?`<div class="sub">${p.gallery.slice(1,3).map(src=>`<button data-image="${src}" aria-label="Mở ảnh lớn"><img src="${src}" alt="${esc(p.short)}"></button>`).join('')}</div>`:''}</div></div><div class="tabs detail-tabs" role="tablist" aria-label="Thông tin địa điểm">${[['overview','Tổng quan'],['photos','Hình ảnh'],['planning','Gợi ý lịch trình'],['reviews','Đánh giá & bằng chứng']].map(([k,l])=>`<button role="tab" data-detail-tab="${k}" aria-selected="${tab===k}">${l}</button>`).join('')}</div>${tab==='photos' ? `<div class="gallery-all">${p.gallery.map(src=>`<button data-image="${src}" aria-label="Mở ảnh lớn"><img src="${src}" alt="${esc(p.short)}"><small>Ảnh Google Maps</small></button>`).join('')}</div>` : tab==='reviews' ? `<div class="detail-layout"><section class="panel pad"><span class="eyebrow">Nguồn thực tế</span><h2>Đánh giá trên Google Maps</h2><div style="margin:20px 0">${rating(p)}</div><p class="small">Điểm sao tổng thể không chứng minh một nơi đáp ứng giới hạn của bạn.</p><a class="text" href="${p.mapsUrl}" target="_blank" rel="noopener">Xem đánh giá gốc ${icon('external')}</a></section><section class="evidence"><span class="eyebrow">Bằng chứng trải nghiệm</span><h2>Một nhận định, một bước tới nguồn.</h2><p style="margin-top:18px">Mock này không chép review cá nhân hoặc dựng clip, cỡ mẫu, trích dẫn giả. Khi production có dữ liệu, hiển thị số người nhắc, bối cảnh, ngày và link nguồn tại từng nhận định.</p>${button('Xem mẫu khối bằng chứng','evidence','soft','style="margin-top:20px"')}</section></div>` : tab==='planning' ? `<div class="detail-layout"><section class="panel pad"><h2>Ghép vào chuyến này</h2><div class="fact-row"><span>Ở lại</span><b class="mono">≈${p.duration} phút</b></div><div class="fact-row"><span>Ngày ghé</span><b>${state.days.findIndex(d=>d.includes(p.id))>=0?'Ngày '+(state.days.findIndex(d=>d.includes(p.id))+1):'Chưa xếp'}</b></div><p class="small" style="margin-top:18px">Giờ ghé phụ thuộc lịch, giờ mở cửa và thời gian di chuyển. Cần kiểm tra trước khi chốt.</p></section><section class="panel pad"><h2>Gọi món gì / làm gì?</h2><p style="margin:20px 0">Chưa có thông tin được gắn bằng chứng trong mock này.</p>${notice('Không suy ra hoạt động chỉ từ loại địa điểm.','warn')}</section></div>` : `<div class="detail-layout"><section><span class="eyebrow">Thông tin thực tế · Maps / chính thức</span><h2>Những điều cần biết</h2><div class="fact-row"><span>Giờ tham khảo</span><div><b>${hours(p)}</b> ${tag('Chưa xác nhận','warn')}<small>Google Maps · catalog ${p.asOf||'chưa có ngày'} · kiểm lại trước khi đi</small></div></div><div class="fact-row"><span>Giá</span><div><b>Chưa có thông tin</b><small>Không coi thiếu giá là miễn phí</small></div></div><div class="fact-row"><span>Đường đi, mức vận động</span><b>Chưa xác minh</b></div><div class="fact-row"><span>Đi cùng ai</span><b>Chưa có bằng chứng đủ</b></div><a class="text" href="${p.mapsUrl}" target="_blank" rel="noopener">${icon('pin')} Mở địa điểm trên Google Maps ${icon('external')}</a>${textButton('Báo thông tin sai','report')}</section><section class="evidence"><span class="eyebrow">Trải nghiệm · Lời người đã đến</span><h2>Vì sao bạn có thể thích nơi này?</h2><p style="margin:16px 0">${reasons[p.id]} Đây là lý do của kịch bản chuyến đi, chưa phải nhận định đã kiểm chứng về nơi.</p>${p.signals?.length?p.signals.map(f=>`<div class="evidence-row"><div><b>${f.label}</b><small style="display:block">${f.n} lượt nhắc · có bằng chứng</small></div>${textButton("Xem nguồn","signal-"+p.id+"-"+f.id)}</div>`).join(''):`<div class="evidence-row"><span>View, độ đông, không gian</span>${tag('Chưa có thông tin','neutral')}</div>`}<div class="evidence-row"><span>Điều kiện tiếp cận</span>${tag('Chưa xác minh','warn')}</div>${textButton(`Bằng chứng được hiển thị thế nào? ${icon('arrow')}`,'evidence')}<p class="small">Fact, signal và estimate được tách rõ. Thiếu bằng chứng luôn giữ “chưa biết”.</p></section></div>`}`; }
function detail() { return `<div class="content">${textButton(`${icon('arrowLeft')} Quay lại lựa chọn`,'nav-explore')}${detailContent(pOf(state.detailId)||PLACES[0])}</div>${selectedBar()}`; }
function variants() {
 const ids = state.selected.length ? [...state.selected] : [2,0,5,8,1,6];
 const overload = state.scenario==='overload' || ids.length>7;
 const locked=ids.filter(id=>state.locked.includes(id));
 const seeds=[[2,0,3,5,1,6],[0,5,8,7,1,6],[2,0,8,5,1,6]];
 const sets = overload ? seeds.map(seed=>{const ordered=[...seed.filter(id=>ids.includes(id)),...ids.filter(id=>!seed.includes(id))];const picked=new Set([...locked,...ordered.filter(id=>!locked.includes(id))].slice(0,6));return ordered.filter(id=>picked.has(id));}) : [ids,ids,ids];
 return [
 {name:overload?'Giữ nơi hợp gu':'Ít di chuyển',desc:overload?'Ưu tiên cà phê và thiên nhiên; bạn quyết định những nơi để dành.':'Gom những nơi gần nhau, dành ít thời gian trên đường.',image:0,travel:overload?165:140,cost:740000},
 {name:overload?'Bớt đi xa':'Nhiều trải nghiệm',desc:overload?'Giữ các cụm gần nhau, bớt những chặng xa trung tâm.':'Cân bằng các loại trải nghiệm trong tập nơi đã chọn.',image:8,travel:overload?95:175,cost:620000},
 {name:'Tiết kiệm hơn',desc:'Cân nhắc chi phí; phần chưa có giá vẫn đánh dấu rõ.',image:1,travel:150,cost:390000}
 ].map((v,i)=>({...v,id:i,keep:sets[i],drop:ids.filter(id=>!sets[i].includes(id)),unavailable:(state.scenario==='unavailable'&&i===2)||(overload&&locked.length>6)}));
}
function tradeoffTable(vs) { return `<div class="panel" style="overflow:auto"><table><caption class="sr">So sánh các phương án minh họa</caption><thead><tr><th>Đánh đổi của cả chuyến</th>${vs.map(v=>`<th>${v.name}</th>`).join('')}</tr></thead><tbody><tr><th>Số nơi giữ</th>${vs.map(v=>`<td>${v.keep.length} nơi · chừa ${v.drop.length}</td>`).join('')}</tr><tr><th>Di chuyển ước tính</th>${vs.map(v=>`<td class="mono">≈${v.travel} phút</td>`).join('')}</tr><tr><th>Chi phí tham khảo / người</th>${vs.map(v=>`<td>${price(v.cost)}<small style="display:block">Minh họa · thiếu giá ăn, ở, di chuyển</small></td>`).join('')}</tr><tr><th>Độ vững</th>${vs.map(v=>`<td>${v.unavailable?tag('Không khả dụng','warn'):tag('Chưa xác nhận trong mock','neutral')}</td>`).join('')}</tr></tbody></table></div>`; }
function choices() { const vs=variants(),overload=state.scenario==='overload'||state.selected.length>7;return `<div class="content choices-content">${heading('Bước 3 · Chọn cách đi',overload?`${state.selected.length} nơi đã chọn. Chọn cách để vừa lịch.`:'Cùng những nơi bạn chọn, vài cách đi.','Mỗi phương án nói rõ phần được giữ và cái giá phải trả. Chọn xong vẫn đổi được.',textButton(`${icon('arrowLeft')} Về lựa chọn`,'nav-explore'))}${state.stay===null?notice(`Chưa chọn chỗ ở: chưa tính đủ đường đi đầu và cuối ngày. ${textButton('Chọn chỗ ở','nav-lodging')}`,'warn','bed'):notice(`Chỗ ở: <b>${esc(STAYS[state.stay]?.name||'đã cung cấp')}</b>. ${textButton('Đổi chỗ ở','nav-lodging')}`)}${state.scenario==='error'?empty('Chưa xếp được lịch','Vướng ở tổ hợp địa điểm. Quay lại lựa chọn để xem cách sửa.','nav-explore','Chọn lại địa điểm'):state.scenario==='loading'?`<div style="margin-top:28px">${loadingCards()}<p class="small" style="margin-top:18px">Đang thử thứ tự ghé và kiểm tra giờ mở cửa…</p></div>`:`<div class="variant-grid">${vs.map(v=>`<article class="variant ${state.variant===v.id?'on':''} ${v.unavailable?'disabled':''}">${photo(PLACES[v.image])}<span class="tag top-badge ${v.unavailable?'warn':'neutral'}">${v.unavailable?'Không có lịch hợp lệ':'Kịch bản minh họa'}</span><div class="body"><h2>${v.name}</h2><p>${v.desc}</p><div class="values"><span><b>${v.keep.length}</b>nơi giữ</span><span><b>≈${v.travel}′</b>di chuyển</span></div>${v.drop.length?`<div class="omitted"><b style="color:var(--warn)">Để dành ${v.drop.length} nơi</b>${v.drop.map(id=>`<div style="margin-top:8px">− ${pOf(id).short}<br><small>${v.id===1?'Xa cụm chính của phương án này':'Ít ưu tiên hơn trong kịch bản này'}</small></div>`).join('')}</div>`:`<div class="omitted">Giữ ${v.keep.map(id=>pOf(id).short).join(' · ')}<br>${textButton('Xem trước từng ngày','preview-variant-'+v.id)}</div>`}<div class="choose"><span>${price(v.cost)}<small style="display:block;font-weight:400">/người · minh họa, chưa đủ giá</small></span>${button(state.variant===v.id?'Đang chọn':'Chọn cách này','variant-'+v.id,state.variant===v.id?'soft':'',v.unavailable?'disabled':'')}</div>${v.unavailable?'<p class="small" style="margin-top:12px">Chưa tìm được lịch đáp ứng giới hạn; không được chọn phương án này.</p>':''}</div></article>`).join('')}</div>${overload?notice(`<b>Giữ tất cả ${state.selected.length} nơi?</b> Cần xem lịch gốc có đạt validation hay không; không nới điều bất khả thi. ${button('Xem đối chiếu Giữ tất cả','keep-all','small')}`,'warn'):''}<h2 style="margin:32px 0 18px">Đặt các đánh đổi cạnh nhau</h2>${tradeoffTable(vs)}`}</div><footer class="sticky-bottom"><div><b>${state.variant===null?'Chọn một phương án':vs[state.variant]?.name||'Phương án của bạn'}</b><p>Giờ, giá và độ vững ở đây là kịch bản minh họa.</p></div>${button(`Xem lịch trình ${icon('arrow')}`,'to-overview','primary',state.variant===null||state.scenario==='loading'||state.scenario==='error'?'disabled':'')}</footer>`; }
function mapMarkup(ids,overview=false) {
 const ps=ids.map(pOf).filter(Boolean),positions=ps.map(p=>{
  const sin=Math.sin(p.lat*Math.PI/180),x=(p.lng+180)/360*4096*256-3279*256,y=(.5-Math.log((1+sin)/(1-sin))/(4*Math.PI))*4096*256-1909*256;
  return {x,y,p};
 });
 const xs=positions.map(p=>p.x),ys=positions.map(p=>p.y),cx=positions.length?(Math.min(...xs)+Math.max(...xs))/2:550,cy=positions.length?(Math.min(...ys)+Math.max(...ys))/2:550,spanX=positions.length?Math.max(...xs)-Math.min(...xs):0,spanY=positions.length?Math.max(...ys)-Math.min(...ys):0;
 return `<div class="map ${overview?'overview-map':''}" data-map-center="${cx},${cy}" data-map-span="${spanX},${spanY}"><div class="map-grid">${Array.from({length:25},(_,i)=>`<img src="assets/map/${3279+i%5}-${1909+Math.floor(i/5)}.png" alt="" loading="lazy">`).join('')}<svg class="map-routes" viewBox="0 0 1280 1280" aria-hidden="true"><path vector-effect="non-scaling-stroke" d="${positions.map((p,i)=>`${i?'L':'M'}${p.x} ${p.y}`).join(' ')}"/></svg>${positions.map(({x,y,p},i)=>`<button class="map-pin" style="left:${x}px;top:${y}px" data-detail="${p.id}" aria-label="Điểm ${i+1}, ${esc(p.short)}"><b>${i+1}</b><span>${p.short}</span></button>`).join('')}</div><div class="map-tools">${tag(overview?'Cả chuyến · sơ đồ minh họa':`Ngày ${state.day+1} · ${ps.length} điểm dừng`,'neutral')}<div class="row">${button(`${icon('external')} Google Maps`,'maps','small')}${overview?button(`Xem từng ngày ${icon('arrow')}`,'nav-day','small'):''}</div></div><div class="map-credit"><span>Đường nối minh họa · không phải chỉ đường</span><a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">© OpenStreetMap contributors</a></div></div>`;
}
function updateMaps() {
 $$('.map[data-map-center]').forEach(map=>{
  const [cx,cy]=map.dataset.mapCenter.split(',').map(Number),[sx,sy]=map.dataset.mapSpan.split(',').map(Number);
  const width=map.clientWidth,height=map.clientHeight,space=map.classList.contains('overview-map')?130:250;
  const scale=Math.min(1.2,(width-150)/(sx+1),(height-space)/(sy+1));
  const grid=$('.map-grid',map);grid.style.transformOrigin=`${cx}px ${cy}px`;grid.style.transform=`translate(${-cx}px,${-cy}px) scale(${Math.max(.3,scale)})`;
 });
}

const DAY_TITLES = ['Săn mây và cà phê Trại Mát','Một chút cà phê, một nhịp chậm','Dạo hồ trước khi về'];
function overview() { const vs=variants(),v=vs[state.variant??0];return `<div class="content">${heading('Bước 3 · Tổng quan',`Đà Lạt, ${state.days.length} ngày của ${state.people===2?'hai bạn':'bạn'}.`,'Mở từng ngày để xem giờ ghé, di chuyển, khoảng nghỉ và điều cần kiểm tra.',textButton('Đổi phương án','nav-choices'))}${guestNotice()}${mapMarkup(state.days.flat(),true)}<section class="overview-flow"><div class="overview-row"><div class="overview-label"><span>Đến Đà Lạt<br><small>${dateLong(0)}</small></span><span class="marker">${icon('route')}</span></div><div class="block"><div class="body"><h3>Di chuyển đến Đà Lạt</h3><p>${state.arrival?`Giờ đến ${state.arrival} · ${esc(state.transport||'cách tới chưa rõ')}`:'Chưa có giờ đến / điểm đến cụ thể.'}</p></div>${textButton('Bổ sung','summary')}</div></div><div class="overview-row"><div class="overview-label"><span>Chỗ nghỉ<br><small>2 đêm</small></span><span class="marker">${icon('bed')}</span></div><div class="block"><div class="body"><h3>${state.stay===null?'Chưa chọn chỗ nghỉ':esc(STAYS[state.stay]?.name||'Chỗ ở đã cung cấp')}</h3><p>${state.stay===null?'Đường đi từ chỗ ở chưa được tính đủ.':'Mọi ngày bắt đầu và kết thúc ở đây.'}</p></div>${textButton(state.stay===null?'Chọn chỗ ở':'Đổi','nav-lodging')}</div></div>${state.days.map((ids,i)=>`<div class="overview-row"><div class="overview-label"><span>Ngày ${i+1}<br><small>${dateLong(i)}</small></span><span class="marker">${icon('calendar')}</span></div><button class="block" data-day="${i}" data-open-day="true">${ids[0]!=null?photo(pOf(ids[0])):''}<div class="body">${tag(`Ngày ${i+1}`)}<h3>${DAY_TITLES[i]||'Một ngày để tự khám phá'}</h3><p>${ids.map(id=>pOf(id).short).join(' · ')||'Khoảng tự do'}</p><div style="margin-top:8px">${tag('Chưa xác nhận độ vững','neutral')}</div></div>${icon('arrow')}</button></div>`).join('')}<div class="overview-row"><div class="overview-label"><span>Rời Đà Lạt<br><small>${dateLong(state.days.length-1)}</small></span><span class="marker">${icon('route')}</span></div><div class="block"><div class="body"><h3>Di chuyển về</h3><p>Giờ rời Đà Lạt: ${state.departure||'chưa rõ'}. Kiểm tra trước khi chốt ngày cuối.</p></div>${textButton('Bổ sung','summary')}</div></div></section><div style="margin-top:28px">${notice(`Phương án: <b>${v.name}</b>. Giá, giờ và đường đi là minh họa; phần chưa biết được đánh dấu tại chỗ.`,'warn')}</div></div><footer class="sticky-bottom"><div><b>${state.days.flat().length} nơi · ${state.days.length} ngày</b><p>${v.name} · chưa phải kế hoạch runtime</p></div><div class="row">${button('Tối ưu lịch','optimize','soft')}${button(`Xem lịch từng ngày ${icon('arrow')}`,'nav-day','primary')}</div></footer>`; }
function stopCard(p,i) { const locked=state.locked.includes(p.id),duration=state.duration[p.id]||p.duration;return `<article class="stop-card"><div class="top"><button class="photo" data-detail="${p.id}" aria-label="Chi tiết ${esc(p.short)}">${photo(p)}</button><div style="flex:1"><span class="eyebrow" style="margin-bottom:5px">${i+1} · ${p.kind}</span><h3>${p.short}</h3>${rating(p)}<p class="small" style="margin-top:8px">${icon('pin')} ${p.area}</p></div></div><div class="bottom"><div><b class="mono">${state.day===0&&i===0?'05:30':i===0?'09:00':'11:00'}</b><small> · Kịch bản giờ ghé</small></div><span>${locked?tag(`${icon('lock')} Nơi đã khóa`):`${textButton('Thời lượng','duration-'+p.id)} · ${duration} phút`}</span></div><div class="controls"><label>Ngày ghé<select data-move="${p.id}" ${locked?'disabled':''}>${state.days.map((_,d)=>`<option value="${d}" ${d===state.day?'selected':''}>Ngày ${d+1}</option>`).join('')}</select></label>${textButton('Xem chi tiết','detail-'+p.id)}</div>${notice(p.id===2?'Phụ thuộc thời tiết. Kiểm tra mây và giờ xuất phát trước khi đi.':'Giờ mở cửa chưa xác nhận — kiểm tra trước khi đi.','warn','warn')}</article>`; }
function day() {
 const ids=state.days[state.day]||[];
 const blocked=state.scenario==='conflict'||state.scenario==='unavailable';
 return `<section class="day-workspace"><div class="day-left"><div class="day-nav">${textButton(`${icon('arrowLeft')} Tổng quan`,'nav-overview')}<div class="tabs" role="tablist" aria-label="Ngày của chuyến">${state.days.map((_,d)=>`<button role="tab" data-day="${d}" aria-selected="${d===state.day}" style="padding:8px 12px">${dateShort(d)}</button>`).join('')}</div></div><div class="day-scroll"><div class="day-heading"><span class="eyebrow">Ngày ${state.day+1} · Đà Lạt</span><h1>${DAY_TITLES[state.day]||'Một ngày để tự khám phá'}</h1><p>${ids.length} điểm dừng · Giờ giấc và đường đi là ước tính.</p><div class="row" style="margin-top:14px">${tag('Chưa xác nhận độ vững','neutral')}${textButton('Xem lý do','robustness')}</div></div>${blocked?notice('<b>Lịch còn lỗi.</b> Không thể tới Cầu Đất trước khung giờ trải nghiệm; điều bất khả thi không có lựa chọn nới. '+textButton('Xem cách sửa','physical-conflict'),'danger','warn'):''}${state.scenario==='loading'?loadingCards(1):ids.map((id,i)=>`${i?`<div class="break-line">${icon('utensils')} Ăn (tự chọn), nghỉ và khoảng đệm</div><p class="leg-line">${icon('bike')} ≈20–35 phút di chuyển · minh họa</p>`:''}${stopCard(pOf(id),i)}`).join('')}${!ids.length?'<div class="panel pad"><h2>Ngày tự do</h2><p style="margin-top:16px">Có thể nghỉ, tự khám phá hoặc quay lại lựa chọn để thêm nơi.</p></div>':''}<div class="break-line">${icon('moon')} Khoảng nghỉ · giữ thời gian tự do</div><section class="panel pad"><h3>Chuẩn bị trước khi đi</h3><p class="small" style="margin:12px 0">Kiểm tra giờ mở cửa, đường đi và giá chưa xác nhận. Các chi phí thuê đồ, trò chơi chỉ cộng khi có bằng chứng.</p>${textButton(`${icon('plus')} Thêm nơi`,'nav-explore')}</section></div><footer class="day-bottom"><div>${state.diff?`${esc(state.diff)} ${textButton('Hoàn tác','undo')}`:'Chưa có thay đổi trong ngày này.'}</div>${button('Chốt kế hoạch này','confirm-plan','primary small',blocked?'disabled':'')}</footer></div><aside class="day-map">${mapMarkup(ids)}<div class="map-insight"><div class="between"><h3>${icon('shield')} Độ vững & dự phòng</h3>${textButton('Xem đầy đủ','backups')}</div><p>Chưa xác nhận trong mock. Xem trước tác động khi đổi nơi hoặc thời lượng; không tự bỏ nơi bạn đã chọn.</p><div class="row">${button('Nếu mưa / đến trễ','backups','soft small')}${button('Tối ưu lịch','optimize','small')}${button(state.stay===null?'Chọn chỗ ở':'Đổi chỗ ở','nav-lodging','small')}</div></div><div class="map-bottom"><span>Chặng đi cần được tính lại sau mỗi thay đổi.</span>${textButton('Theo hành trình','nav-overview')}</div></aside></section>`;
}
function done() { return `<div class="content narrow" style="max-width:720px">${guestNotice()}<div class="feedback-hero"><span class="seal">${icon(state.feedbackSent?'heart':'check')}</span><span class="eyebrow">Chuyến Đà Lạt của bạn</span><h1>${state.feedbackSent?'Cảm ơn bạn.':'Kế hoạch đã chốt.'}</h1><p>${state.feedbackSent?'Phản hồi được giữ trong prototype này để bạn xem luồng.':'Vài câu ngắn thôi, bỏ qua được hết. Câu trả lời giúp mình gợi ý đúng hơn lần sau.'}</p><small>Chốt trong mock là mô phỏng; không tạo kế hoạch trên máy chủ.</small></div>${state.feedbackSent?`<div class="row" style="justify-content:center">${button('Xem lại lịch','nav-overview')}${button('Đến Chuyến của tôi','nav-trips','primary')}</div>`:`<form data-form="feedback" class="panel pad">${[['fit','Gợi ý có đúng gu của bạn?'],['clear','Lý do dễ hiểu?'],['realistic','Lịch có thực tế?'],['confident','Bạn tự tin hơn về chuyến đi?']].map(([id,q])=>`<fieldset class="score-field"><legend>${q}</legend><div class="score-buttons" role="radiogroup" aria-label="${q}">${[1,2,3,4,5].map(n=>`<button class="score" type="button" role="radio" data-score="${id}:${n}" aria-checked="${state.feedback[id]===n}">${n}</button>`).join('')}</div><div class="score-ends"><span>Chưa đúng</span><span>Rất đúng</span></div></fieldset>`).join('')}<fieldset style="margin:20px 0"><legend>Bạn còn phải tìm chỗ khác nữa không?</legend><div class="row">${['Có','Không'].map(l=>`<button type="button" class="chip" data-more="${l}" aria-pressed="${state.feedback.more===l}">${l}</button>`).join('')}</div></fieldset><label>Góp ý thêm (không bắt buộc)<textarea name="note" placeholder="Điều gì mình làm chưa tốt?">${esc(state.feedback.note||'')}</textarea></label><div class="row" style="margin-top:24px"><button type="submit" class="btn primary">Gửi phản hồi</button>${textButton('Bỏ qua','nav-trips')}${textButton('Mở Hôm nay','nav-today')}</div></form>`}</div>`; }
function trips() { return `<div class="content">${heading('Chuyến của tôi','Những chuyến của bạn.','Tài khoản mở được chuyến trên mọi máy. Với khách, chuyến bị xóa sau 24 giờ không hoạt động.',button(`${icon('plus')} Tạo chuyến đi`,'new-trip','primary'))}${guestNotice()}${state.scenario==='loading'?loadingCards():state.scenario==='empty'||state.emptyTrips?empty('Chưa có chuyến đi nào','Kể một câu ở Khám phá để bắt đầu chuyến đầu tiên.','nav-discover','Khám phá Đà Lạt'):`<div class="grid3">${[['Đang lập',0,'16–18 tháng 10','resume','Đi tiếp'],['Đã chốt',2,'16–18 tháng 10','nav-overview','Xem lịch'],['Đã đi',1,'02–04 tháng 10','nav-done','Phản hồi']].map(([status,id,date,action,label],i)=>`<article class="panel trip-card">${photo(PLACES[id])}<div class="body">${tag(status,i===0?'neutral':'')}<h2>Đà Lạt 3 ngày</h2><p class="mono">${date} · 2 người</p><p>${i===0?state.selected.length:6} nơi · Cà phê & thiên nhiên</p><div class="progress" aria-label="${status}">${[0,1,2].map(n=>`<i class="${i>0||n<1?'done':''}"></i>`).join('')}</div><div class="row">${button(label,action,'primary small')}${textButton(i===1?'Sửa lại':i===2?'Xem lại lịch':'Ẩn khỏi danh sách',i===1?'edit-confirmed':i===2?'nav-overview':'hide-trip')}</div></div></article>`).join('')}</div>`}</div>`; }
function saved() { const ps=state.saved.map(pOf).filter(Boolean).filter(p=>state.group==='all'||p.group===state.group);return `<div class="content">${heading('Đã lưu','Những nơi muốn để dành.','Lưu trên trình duyệt này. Nơi đã lưu không tự vào lịch; chỉ thêm nếu nằm trong gợi ý của chuyến hiện tại.')}<div class="tabs" role="tablist" aria-label="Nhóm nơi đã lưu">${[['all','Tất cả'],['food','Cà phê'],['sight','Thiên nhiên']].map(([g,l])=>`<button role="tab" aria-selected="${state.group===g}" data-group="${g}">${l}</button>`).join('')}</div><div style="margin-top:24px">${state.scenario==='empty'||!ps.length?empty('Chưa có nơi trong nhóm này','Bấm trái tim trên một địa điểm để giữ lại cho lần sau.','nav-explore','Xem gợi ý'): `<div class="catalog-grid">${ps.map(p=>cardPlace(p,true)).join('')}</div>`}</div></div>`; }
function today() {
 if (state.guest||state.scenario==='guest') return `<div class="content narrow">${empty('Hôm nay cần đăng nhập Google','Đăng nhập để giữ các chuyến đã lập và dùng Hôm nay, thông báo, Google Calendar.','google','Đăng nhập để lưu chuyến')}</div>`;
 if(state.scenario==='empty') return `<div class="content narrow">${empty('Chưa có chuyến nào đã chốt','Chốt lịch trình xong, màn này đi cùng bạn trong chuyến. Bấm Đã đến là tự nguyện.','nav-trips','Xem chuyến của tôi')}</div>`;
 const ids=state.days[state.day]||[],here=ids.find(id=>state.checkins[id]);
 return `<div class="content">${heading('Hôm nay · Chuyến đã chốt',`Ngày ${state.day+1} · ${dateLong(state.day)}`,'Bấm Đã đến khi tới nơi để xem nên chơi gì ở đây. Không bấm cũng không sao.',`<div class="row">${button(`${icon('calendar')} Calendar`,'calendar')}${button(`${icon('pin')} Tôi đang ở nơi khác`,'other-place')}</div>`)}<div class="between"><div class="tabs" role="tablist" aria-label="Ngày">${state.days.map((_,d)=>`<button role="tab" data-day="${d}" aria-selected="${d===state.day}">Ngày ${d+1}</button>`).join('')}</div>${button('Xem kế hoạch','nav-overview','small')}</div><div style="margin-top:22px">${notice(`Một vài thông báo đúng lúc, nếu bạn muốn. ${textButton(state.notifies.enabled?'Đã bật thông báo':'Bật thông báo','enable-notifications')}`)}</div>${state.scenario==='overload'?`<div style="margin-top:18px">${notice(`Phần còn lại hơi chật. ${textButton('Xem cách điều chỉnh','late-adjust')}`,'warn')}</div>`:''}<div class="today-layout"><section>${ids.map((id,i)=>{const p=pOf(id);return `<article class="panel today-stop"><div class="time mono">${i?'11:00':'05:30'}<small style="display:block">ước tính</small></div>${photo(p)}<div class="body"><h3>${p.short}</h3><p>${p.kind} · ${p.area}</p><p class="small" style="margin-top:8px">Giờ mở cửa chưa xác nhận · kiểm tra trước khi đi</p>${state.checkins[id]?`<div class="row">${tag(`${icon('check')} Đã đến`)}${button('Ở đây có gì','here-'+id,'soft small')}${button(`${icon('check')} Hợp`,'rate-'+id+'-1','small',`aria-pressed="${state.ratings[id]===1}"`)}${button('Không hợp','rate-'+id+'--1','small',`aria-pressed="${state.ratings[id]===-1}"`)}</div>`:state.skipped[id]?`<div class="row">${tag('Đã bỏ qua','neutral')}${textButton('Hoàn tác','unskip-'+id)}</div>`:`<div class="row">${button('Đã đến','checkin-'+id,'primary small')}${button('Bỏ qua','skip-'+id,'small')}</div>`}</div></article>`;}).join('')}<p class="small">Chưa check-in vẫn là “đang dự kiến”, không gắn nhãn lỡ hay thất bại.</p></section><aside class="panel pad today-side">${here!==undefined ? `<span class="eyebrow">Ở đây</span><h2>${pOf(here).short}</h2>${photo(pOf(here))}<h3>Chơi gì ở đây?</h3><p style="margin:12px 0">Chưa có nội dung gắn bằng chứng trong mock. Xem chi tiết nơi và kiểm tra lưu ý thực tế trước khi quyết định.</p>${button('Chi tiết & bằng chứng','detail-'+here,'soft')}<h3 style="margin:24px 0 12px">Gần đây / nơi tương tự</h3><p>Chỉ thêm sau khi kiểm tra quãng đường và thời gian tới điểm sau.</p>${textButton('Xem gợi ý minh họa','nearby')}` : `<span class="eyebrow">Chuyến đi của bạn</span><h2>Lịch gọn, đi nhẹ.</h2><p>Đã đến rồi mới mở gợi ý tại chỗ. Bạn không cần chia sẻ vị trí GPS.</p><div class="receipt"><h3>${icon('calendar')} Google Calendar</h3><p style="margin:12px 0">${state.calendar?'Đã xuất trong kịch bản mock.':'Xem trước mọi mục sẽ ghi trước khi xác nhận.'}</p>${button(state.calendar?'Xem lại bản xuất':'Xem trước lịch Google','calendar','soft small')}</div><div style="margin-top:24px">${textButton('Nếu đến trễ, xem cách sửa','late-adjust')}</div>`}</aside></div></div>`;
}
function inbox() { if(state.guest||state.scenario==='guest')return `<div class="content narrow">${empty('Thông báo cần đăng nhập Google','Khách chưa dùng được thông báo, Hôm nay và Calendar. Đăng nhập để giữ chuyến đã lập.','google','Đăng nhập để lưu chuyến')}</div>`;return `<div class="content narrow">${heading('Thông báo','Ít thôi, đúng lúc thôi.','Tắt từng loại trong Hồ sơ. Thông báo có nội dung để hành động, không thêm áp lực.',textButton('Cài đặt thông báo','nav-profile'))}${state.scenario==='empty'?empty('Chưa có thông báo nào','Khi có chuyến đã chốt, những nhắc nhở hữu ích sẽ nằm ở đây.','nav-today','Mở Hôm nay'):state.scenario==='loading'?loadingCards(1):`<ul class="panel inbox-list">${[['Bản tin cho ngày đầu','Kiểm tra thời tiết trước buổi săn mây. Các giờ mở cửa chưa xác nhận cần xem lại.','07:00 · 16/10','nav-today','sun'],['Kế hoạch đã được điều chỉnh','Bạn vừa áp dụng thay đổi thời lượng. Xem lại lịch ngày bị ảnh hưởng.','18:40 · 13/10','nav-day','calendar'],['Chuẩn bị trước chuyến đi','Xem những thông tin còn chưa xác nhận trước khi khởi hành.','18:00 · 13/10','nav-overview','shield']].map(([title,body,time,action,ic],i)=>`<li class="${state.read.includes(i)?'':'new'}"><button data-notification="${i}" data-notification-action="${action}"><span class="icon-btn">${icon(ic)}</span><div class="body"><h3>${title}</h3><p>${body}</p><small>${time} · Nội dung minh họa</small></div>${!state.read.includes(i)?tag('Chưa đọc'):''}</button></li>`).join('')}</ul>`}</div>`; }
function profile() { if(state.guest||state.scenario==='guest') return `<div class="content narrow">${heading('Khách','Bạn đang dùng không cần tài khoản.','Lập chuyến đầy đủ, nhưng không có hồ sơ dài hạn, Hôm nay, thông báo và Calendar.')}<div class="row">${button('Đăng nhập bằng Google để lưu chuyến','google','primary')}${button('Kết thúc và xóa chuyến khách','end-guest','danger')}</div></div>`;return `<div class="content">${heading('Hồ sơ và dữ liệu','Bạn và dữ liệu của bạn.','Mọi trường đều tùy chọn. Hồ sơ chỉ là gợi ý ban đầu; điều bạn nói cho chuyến này luôn thắng.')}<div class="profile-layout"><div class="stack"><section class="panel pad"><div class="profile-id"><span class="avatar">AN</span><div><h3>${esc(state.profile.name)}</h3><p class="small">Tài khoản minh họa</p>${textButton('Đổi avatar','avatar')}</div></div><form data-form="profile"><div class="form-grid"><label>Tên hiển thị<input name="name" value="${esc(state.profile.name)}"></label><label>Thành phố hay xuất phát<input name="origin" value="${esc(state.profile.origin)}"></label><label>Phương tiện hay dùng<select name="mobility">${['Xe máy','Ô tô','Taxi / đặt xe'].map(v=>`<option ${state.profile.mobility===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Hay đi cùng ai<select name="companions">${['Người yêu','Bạn bè','Bố mẹ','Một mình'].map(v=>`<option ${state.profile.companions===v?'selected':''}>${v}</option>`).join('')}</select></label></div><p class="small" style="margin:18px 0">Các giá trị hiện với nhãn “từ hồ sơ”, sửa được khi bắt đầu chuyến.</p><button type="submit" class="btn primary">Lưu hồ sơ</button></form></section><section class="panel pad"><h2>Sở thích của chuyến hiện tại</h2><p class="small" style="margin:12px 0 18px">Đây là mong muốn cho chuyến này, không phải constraint lâu dài.</p><div class="row">${state.prefs.map(v=>tag(v+' · bạn nói')).join('')}<span class="chip prior">Ít đông · từ hồ sơ</span></div>${textButton('Sửa trong tóm tắt chuyến đi','summary')}</section><section class="panel pad"><div class="between"><div><h3>Xóa tài khoản</h3><p class="small" style="margin-top:8px">Xóa hồ sơ, ảnh, liên kết Calendar và thông báo. Số liệu còn lại không gắn với bạn.</p></div>${button('Xóa tài khoản','delete-account','danger small')}</div></section></div><div class="stack"><section class="panel pad"><h2>Thông báo</h2>${[['morning','Bản tin sáng'],['sunset','Giờ hoàng hôn'],['booking','Nhắc chuẩn bị / đặt trước']].map(([k,l])=>`<div class="setting-row"><div><b>${l}</b><p>Chỉ khi có dữ liệu và chuyến phù hợp.</p></div><button class="switch" role="switch" aria-label="${l}" aria-checked="${state.notifies[k]}" data-switch="${k}"></button></div>`).join('')}<div class="setting-row"><b>Tạm im thông báo</b><button class="switch" role="switch" aria-label="Tạm im thông báo" aria-checked="${!!state.notifies.quiet}" data-switch="quiet"></button></div></section><section class="panel pad"><h2>Google Calendar</h2><p class="small" style="margin:14px 0">${state.calendar?'Đã kết nối trong mock.':'Chưa kết nối. Kết nối và xuất từ Hôm nay.'} Chỉ ghi sau khi bạn xem trước và xác nhận.</p>${state.calendar?button('Ngắt kết nối','disconnect-calendar','small'):button('Mở Hôm nay','nav-today','soft small')}</section><section class="panel pad"><h3>Dữ liệu và quyền của bạn</h3><p class="small" style="margin-top:12px">Không thu GPS. Nơi đã đến không tự trở thành nơi đã thích. Phản hồi Hợp / Không hợp do bạn chọn.</p>${textButton('Đăng xuất','signout')}</section></div></div></div>`; }
function atlas() {
 const decisions=[['Khám phá trong app','Học sidebar có nhãn và phân cấp ảnh của homepage mock.','Bỏ cột bạn bè, activity feed, “đã xem gần đây”: production chưa có. Giữ ô kể chuyến, chủ đề mở chuyến và chuyến đang lập.','web/src/user/screens/Discover.tsx'],['Hiểu chuyến đi','Học chat rộng, danh sách xem trước bên phải, tóm tắt mở riêng.','Giữ các card hỏi và nguồn dữ liệu của production. Không checkbox chọn nơi ở bước hiểu chuyến; không cắt tiêu đề hoặc dùng cuộn cả trang cho composer.','web/src/user/screens/Understand.tsx'],['Lựa chọn','Học thẻ thoáng, ảnh có tỷ lệ ổn định; thống nhất màu với workspace.','Giữ lý do, đánh đổi, khóa, so sánh, thanh Đã chọn, khả thi và trợ lý của production. Không tự tuyển chọn thay user.','web/src/user/screens/Explore.tsx'],['Chi tiết địa điểm','Giữ layout chia đôi và gallery của production.','Không thay bằng popup nhỏ trong mock cũ. Giữ 4 tab, nguồn + ngày, thông tin thiếu, bằng chứng và báo sai.','web/src/user/ui/PlaceSheet.tsx'],['Chỗ ở','Dùng độ thoáng và thẻ cân đối của mock.','Giữ một chỗ ở cả chuyến, giá tham khảo có ngày, tìm chỗ khác, xác nhận khi đổi. Không giả điểm hợp gu khi thiếu bằng chứng.','web/src/user/screens/Lodging.tsx'],['Chọn phương án','Học thẻ phương án có một ảnh, phần chừa rõ và lý do.','Giữ bảng đánh đổi, unavailable, Giữ tất cả và validation của production. Không bắt mọi chuyến đều phải bỏ 3 nơi.','web/src/user/screens/Plan.tsx'],['Lịch trình','Học tổng quan → từng ngày, danh sách trái / bản đồ phải.','Giữ chuyển ngày ghé, sửa thời lượng qua preview, backup, tối ưu, hoàn tác, cảnh báo tại nơi. Bỏ drag reorder và “Căn lại giờ” của mock cũ vì production chưa hỗ trợ.','web/src/user/screens/Plan.tsx'],['Sau khi chốt','Giữ nội dung và thao tác production, áp hệ thị giác thống nhất.','Check-in tự nguyện, bỏ qua không phạt, Hợp / Không hợp riêng, Calendar xem trước → xác nhận; xóa tài khoản hai bước.','web/src/user/screens/Today.tsx'],['Phạm vi','User Web desktop production hiện tại, toàn bộ luồng và màn phụ.','Landing và Admin không thuộc bề mặt production public trong yêu cầu này. Điện thoại giữ màn Dùng ứng dụng của production.','web/src/user/UserApp.tsx']];
 return `<div class="content review-atlas">${heading('Bộ thiết kế · 21 màn và nhóm review','Một hệ UI, trọn hành trình.','Prototype độc lập cho User Web production. Mỗi màn mở được trực tiếp, mọi luồng chính nối với nhau.',button('Đi thử từ đăng nhập','nav-login','primary'))}<section class="panel pad"><div class="row">${['login','discover','understand','explore','lodging','choices','overview','day','done','today'].map((id,i)=>`${i?icon('arrow'):''}<a class="chip" href="#${id}">${SCREEN_NAMES[id].split(' · ')[1]}</a>`).join('')}</div><p class="small" style="margin-top:20px">Luồng phụ: Chi tiết ↔ So sánh; Chuyến của tôi → đi tiếp / sửa / phản hồi; Hôm nay → Đã đến → Ở đây → Calendar; Hồ sơ → thông báo / ngắt Calendar / xóa tài khoản.</p></section><h2 class="section-title">Mở từng màn để review</h2><div class="grid3">${Object.entries(SCREEN_NAMES).filter(([id])=>!['atlas','states','system'].includes(id)).map(([id,name])=>`<article class="panel screen-card"><span class="screen-id">${name.split(' · ')[0]}</span><h3>${name.split(' · ')[1]}</h3><p>${ROUTES[id]||'Màn con / trạng thái trong hành trình'}</p>${textButton(`Mở màn ${icon('arrow')}`,'nav-'+id)}</article>`).join('')}</div><h2 class="section-title">Học, bỏ và giữ</h2><div class="panel" style="overflow:auto"><table><thead><tr><th>Bề mặt</th><th>Điểm học từ mock</th><th>Giữ / bỏ có chủ đích</th></tr></thead><tbody>${decisions.map(([name,learn,retain,file])=>`<tr><th><b>${name}</b><small style="display:block;margin-top:8px">${file}</small></th><td>${learn}</td><td>${retain}</td></tr>`).join('')}</tbody></table></div><div class="grid2" style="margin-top:28px"><section class="panel pad"><h2>Trạng thái và tương tác</h2><p style="margin:14px 0">Menu review trên cùng đổi màn / trạng thái. Đây là công cụ cho designer, không phải điều hướng của sản phẩm.</p>${button('Mở thư viện trạng thái','nav-states','soft')}</section><section class="panel pad"><h2>Hệ thị giác chung</h2><p style="margin:14px 0">Nền giấy, xanh thông, ảnh thật; font serif cho tiêu đề và sans cho thao tác. Không đổi palette giữa các phase.</p>${button('Xem nền tảng','nav-system','soft')}</section></div></div>`;
}
const ROUTES={login:'/app/login',consent:'/app/login · consent',discover:'/app',understand:'/app/understand',import:'/app/understand · card khớp nơi',explore:'/app/explore',lodging:'/app/explore · tab Chỗ ở',detail:'/app/explore/place/:id hoặc ?place=:id',compare:'/app/explore/compare/:ids',choices:'/app/plan · chọn phương án',overview:'/app/plan · Hành trình',day:'/app/plan · Theo giờ',done:'/app/done',today:'/app/today',trips:'/app/trips',saved:'/app/saved',inbox:'/app/inbox',profile:'/app/profile'};
function states() {return `<div class="content">${heading('Thư viện · Trạng thái và component','Đầy đủ cả lúc mọi thứ chưa sẵn sàng.','Mỗi trạng thái có câu giải thích, dữ liệu còn giữ và một đường đi tiếp.')}<div class="grid3">${[['Đang hiểu nhu cầu','Composer vẫn có vị trí cố định; hỏi đúng việc đang làm, không có % giả.','understand','loading'],['Lỗi trợ lý','Giữ transcript và lối Thử lại.','understand','error'],['Không có kết quả','Nêu giới hạn và dẫn tới tóm tắt để user sửa.','explore','empty'],['Thiếu thông tin','Chưa biết không trở thành không / miễn phí / an toàn.','detail','unknown'],['Xung đột user constraint','Nêu nơi, quy tắc, cách sửa và cái giá khi nới.','explore','conflict'],['Quá tải tổ hợp','Ba hướng, chừa có lý do, giữ tất cả chỉ khi validation đạt.','choices','overload'],['Phương án không khả dụng','Giữ thẻ và lý do; nút chọn disabled.','choices','unavailable'],['Physical constraint','Không thể tới đúng khung giờ; không có lựa chọn nới.','day','conflict'],['Chưa có chuyến','CTA dẫn vào Khám phá.','trips','empty'],['Chưa có lịch đã chốt','Hôm nay dẫn về Chuyến của tôi.','today','empty'],['Khách cần lưu chuyến','Google sign-in giữ chuyến khách; Hôm nay và Calendar cần tài khoản.','today','guest'],['Hôm nay đến trễ','Thông báo trung tính, preview cách sửa trước khi xác nhận.','today','overload']].map(([title,body,screen,scenario])=>`<article class="panel state-card"><h3>${title}</h3><p>${body}</p>${textButton('Mở trạng thái '+icon('arrow'),'scenario-'+screen+'-'+scenario)}</article>`).join('')}</div><h2 class="section-title">Thành phần dùng chung</h2><div class="grid2"><section class="panel pad"><h3>Nhãn dữ liệu</h3><div class="row" style="margin:20px 0">${tag('Có nguồn · ngày')}${tag('Chưa xác nhận','warn')}${tag('Chưa có thông tin','neutral')}</div>${notice('Một số thông tin có thể đã đổi. Kiểm tra lần cuối theo ngày của nguồn.','warn')}<p class="small" style="margin-top:18px">Confidence không suy từ điểm sao. Signal luôn kèm cỡ mẫu khi có dữ liệu; estimate luôn có ≈ hoặc khoảng.</p></section><section class="panel pad"><h3>Constraint và sở thích</h3><div class="row" style="margin:20px 0"><span class="chip hard">${icon('lock')} Mỗi chặng ≤30 phút</span><span class="chip">Cà phê · bạn nói</span><span class="chip prior">Ít đông · từ hồ sơ</span></div><p class="small">Giới hạn cứng cần xác nhận để nới. Sở thích từ hồ sơ là prior sửa được, không phải fact hay constraint.</p></section><section class="panel pad"><h3>Preview → xác nhận → hoàn tác</h3><p class="small" style="margin:16px 0">Thao tác đổi thời lượng, chuyển ngày và dự phòng nói rõ phần lịch bị ảnh hưởng.</p><div class="row">${button('Thử sửa thời lượng','duration-0','soft')}${button('Thử đổi chỗ ở','stay-1')}${textButton('Hoàn tác','undo')}</div></section><section class="panel pad"><h3>Trạng thái quyết định của thẻ</h3><div class="row" style="margin:18px 0">${tag('Đã chọn')}${tag(icon('lock')+' Nơi đã khóa')}${tag('Đang so sánh','neutral')}</div><p class="small">Thao tác hiện rõ, không lệ thuộc hover. Khóa tách khỏi lưu trái tim; thả tim không tự thêm vào chuyến.</p></section></div><h2 class="section-title">Các dialog có thể thử</h2><div class="row">${[['summary','Tóm tắt chuyến đi'],['selected','Danh sách đã chọn'],['conflicts','Sửa giới hạn'],['backups','Dự phòng'],['optimize','Tối ưu'],['calendar','Calendar'],['delete-account','Xóa tài khoản'],['report','Báo thông tin sai']].map(([action,label])=>button(label,action)).join('')}</div></div>`;}
function system() {return `<div class="content">${heading('Nền tảng · Hệ thị giác','Giấy sáng. Xanh thông. Ảnh thật.','Một bộ token dùng từ khám phá đến Hôm nay, ưu tiên đọc rõ và thấy đúng thao tác.')}<section class="panel pad"><h2>Màu và vai trò</h2><div class="swatches" style="margin-top:24px">${[['Nền giấy','--bg','#faf7f2'],['Bề mặt','--surface','#ffffff'],['Mực','--ink','#1b2a2f'],['Chữ phụ','--muted','#52636a'],['Thông','--pine','#0f5f5a'],['Thông nhạt','--soft','#e3f1ee'],['Hổ phách','--warn','#8a5a00'],['Nguy hiểm','--danger','#b42318']].map(([name,token,hex])=>`<div class="swatch"><i style="background:var(${token})"></i><b>${name}</b><small>${hex}</small></div>`).join('')}</div></section><div class="grid2" style="margin-top:26px"><section class="panel pad"><span class="eyebrow">Type & hierarchy</span><h1>Chuyến này,<br>đúng gu bạn.</h1><h2 style="margin-top:24px">Tiêu đề trang / nhóm nội dung</h2><p style="margin-top:16px">Nội dung dùng Inter / system sans, số dùng mono. Font serif có fallback Georgia cho mock mở offline.</p><span class="mono" style="display:block;margin-top:20px">05:30 · ≈60–90 phút · 992.000đ</span><p class="small" style="margin-top:16px">Body 16 px · caption 12–13 px · heading 28–48 px</p></section><section class="panel pad"><span class="eyebrow">Hành động</span><div class="row">${button('Hành động chính','sample-primary','primary')}${button('Thao tác phụ','sample-secondary','soft')}${button('Chưa khả dụng','noop','','disabled')}${icButton('heart','Lưu mẫu','sample-save')}</div><p style="margin:24px 0 16px">Mục tiêu bấm 44 px, focus ring 3 px. Giảm chuyển động theo tùy chọn hệ điều hành.</p><div class="row">${['compass','calendar','pin','clock','route','heart','shield','bell','lock','users','bed','sparkle'].map(n=>`<span class="icon-btn">${icon(n)}</span>`).join('')}</div></section></div><section class="panel pad" style="margin-top:26px"><h2>Bố cục desktop</h2><table><tbody><tr><th>1024–1280</th><td>2 cột thẻ · chat + panel xem trước · lịch 2 vùng cuộn độc lập</td></tr><tr><th>1440–1600</th><td>3 cột thẻ · gutter 40 px · sidebar 220 px · tiêu đề thoáng</td></tr><tr><th>1920+</th><td>4 cột thẻ · max nội dung 1680 px · không phóng chữ hoặc kéo đoạn văn vô hạn</td></tr><tr><th>Điện thoại</th><td>Giữ phạm vi production: trang Dùng ứng dụng, chưa dựng thêm mobile app</td></tr></tbody></table></section></div>`;}
const SCREENS={login:()=>auth(),consent:()=>auth(true),discover,understand,import:imported,explore,lodging,detail,compare,choices,overview,day,done,trips,saved,today,inbox,profile,atlas,states,system};
function showDialog(title,body,footer='',wide=false,kind='') {
 const d=$('#dialog');if(!d.open)dialogReturn=document.activeElement;dialogKind=kind;
 d.className=wide?'wide':'';d.innerHTML=`<header class="dialog-head"><h2 id="dialog-title">${title}</h2>${icButton('x','Đóng dialog','close')}</header><div class="dialog-content">${body}</div>${footer?`<footer class="dialog-footer">${footer}</footer>`:''}`;
 if(!d.open)d.showModal();d.scrollTop=0;
}
function closeDialog() { const d=$('#dialog');if(d.open)d.close();modalPlace=null;dialogKind=''; }
$('#dialog').addEventListener('close',()=>{if(dialogReturn?.isConnected)dialogReturn.focus();modalPlace=null;dialogKind='';});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')) {const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
function openDetail(id) { const p=pOf(id);if(!p)return;state.detailId=p.id;state.detailTab='overview';modalPlace=p.id;showDialog('Chi tiết địa điểm',detailContent(p,true),'',true,'detail');modalPlace=p.id; }
function summary() {
 const val=key=>esc(state[key]??'');
 showDialog('Tóm tắt chuyến đi',`<span class="eyebrow">Từ những điều bạn đã kể</span><p>Kiểm tra những gì mình hiểu. Phần chưa rõ giữ riêng; hồ sơ chỉ là gợi ý sửa được.</p><form id="summary-form" data-form="summary" class="stack" style="margin-top:22px"><h3>Thông tin chuyến này</h3><div class="form-grid"><label>Ngày bắt đầu<input name="date" type="date" value="${state.date}"></label><label>Số ngày<input name="days" type="number" min="1" max="14" value="${state.days.length}" required></label><label>Số người<input name="people" type="number" min="1" max="20" value="${state.people}" required></label><label>Đi cùng ai<select name="companions">${['Người yêu','Bạn bè','Bố mẹ','Có trẻ em','Một mình','Chưa rõ'].map(v=>`<option ${(state.companions||'Người yêu')===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Nhịp đi<select name="pace">${['Thong thả','Cân bằng','Đi nhiều','Chưa rõ'].map(v=>`<option ${state.pace===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Phương tiện tại Đà Lạt<select name="mobility">${['Xe máy','Ô tô','Taxi / đặt xe','Đi bộ','Chưa rõ'].map(v=>`<option ${(state.mobility||'Xe máy')===v?'selected':''}>${v}</option>`).join('')}</select></label></div><details open><summary><b>Đi lại & khung giờ</b></summary><div class="form-grid" style="margin-top:18px"><label>Điểm xuất phát<input name="origin" value="${val('origin')}" placeholder="Chưa có thông tin"></label><label>Cách tới Đà Lạt<select name="transport">${['Chưa rõ','Tự đi','Xe khách','Máy bay'].map(v=>`<option ${(state.transport||'Chưa rõ')===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Giờ tới Đà Lạt<input type="time" name="arrival" value="${val('arrival')}"></label><label>Giờ rời Đà Lạt<input type="time" name="departure" value="${val('departure')}"></label><label>Giờ kết thúc mỗi ngày<input type="time" name="dayEnd" value="${val('dayEnd')}"></label><label>Chỗ ở đã đặt / ghi chú<input name="bookedText" value="${val('bookedText')}" placeholder="Chưa có; chọn ở bước Lựa chọn"></label></div><p class="small" style="margin-top:16px">Gõ tên chỗ ở ở đây chỉ giữ ghi chú; chọn đúng địa điểm ở tab Chỗ ở để làm điểm bắt đầu và kết thúc.</p>${textButton(state.stay===null?'Chọn chỗ ở':'Xem / đổi chỗ ở','nav-lodging')}</details><details open><summary><b>Ngân sách & giới hạn</b></summary><div class="form-grid" style="margin-top:18px"><label>Ngân sách cả chuyến (đồng)<input name="budget" type="number" min="0" step="10000" value="${val('budget')}" placeholder="Chưa có giới hạn"></label><label>Tối đa mỗi chặng (phút)<input name="maxLeg" type="number" min="1" max="240" value="${val('maxLeg')}" placeholder="Chưa có giới hạn"></label><label>Đường dốc<select name="avoidSteep"><option value="unknown" ${state.avoidSteep==null?'selected':''}>Chưa có yêu cầu</option><option value="true" ${state.avoidSteep===true?'selected':''}>Phải tránh đường dốc</option><option value="false" ${state.avoidSteep===false?'selected':''}>Không đặt giới hạn về đường dốc</option></select></label></div><p class="small" style="margin-top:16px">Giới hạn cứng loại nơi thiếu bằng chứng đáp ứng. Điều bất khả thi vật lý không thể nới.</p></details><section><h3>Gu & điều cần giữ</h3><div class="row">${['Cà phê','Thiên nhiên','Săn mây','Ít đông'].map(v=>`<label class="chip" style="flex-direction:row;font-weight:400"><input type="checkbox" name="prefs" value="${v}" ${state.prefs.includes(v)?'checked':''}>${v}</label>`).join('')}</div><p class="small" style="margin-top:16px">Chọn / bỏ sở thích để đổi gu chuyến này. “Ít đông” từ hồ sơ vẫn là gợi ý, không tự thành giới hạn cứng.</p><div class="row" style="margin-top:16px">${state.locked.map(id=>`<span class="chip hard">${icon('lock')} Giữ ${pOf(id).short}</span>`).join('')||'<p class="small">Chưa khóa nơi bắt buộc đến.</p>'}</div></section>${state.messages.length?`<h3>Ghi chú từ lời bạn</h3><ul>${state.messages.map(m=>`<li>${esc(m)}</li>`).join('')}</ul>`:''}</form>`,`${button('Đóng','close')}<button class="btn primary" type="submit" form="summary-form">Lưu thay đổi</button>`);
}

function selectedDialog() {showDialog('Những nơi đã chọn',`<p>Khóa để giữ nơi bắt buộc. Bỏ một nơi không xóa nó khỏi danh sách đã lưu.</p><div style="margin-top:18px">${state.selected.map(id=>{const p=pOf(id);return `<div class="summary-field" style="align-items:center"><div class="row">${photo(p,'','style="width:60px;height:60px;border-radius:12px"')}<b>${p.short}</b></div><div class="row">${icButton('lock','Khóa '+p.short,'lock-'+id,`aria-pressed="${state.locked.includes(id)}"`)}${button('Bỏ','remove-'+id,'small',state.locked.includes(id)?'disabled':'')}</div></div>`;}).join('')||'<p>Chưa chọn nơi nào.</p>'}</div>`,button('Tiếp tục lựa chọn','nav-explore','primary'),'','selected');}
function conflicts(physical=false) {showDialog(physical?'Chưa thể ghé đúng giờ':'Một chặng vượt giới hạn',`<span class="eyebrow">${physical?'Điều bất khả thi':'Giới hạn của chuyến này'}</span><h3>Săn mây Cầu Đất</h3><p>${physical?'Theo kịch bản này, sớm nhất đến 08:10, ngoài khung trải nghiệm đã chọn. Không có lựa chọn nới điều vật lý.':'Chặng tới Cầu Đất ≈42 phút, bạn đặt tối đa 30 phút. Mình không tự nới.'}</p><div class="stack" style="margin-top:22px">${button(state.locked.includes(2)?'Cầu Đất đã khóa · cần mở khóa trước':'Để dành Cầu Đất · bớt một chặng xa','conflict-save-later','soft',state.locked.includes(2)?'disabled':'')}${physical?button('Quay lại sửa ngày / giờ xuất phát','nav-understand'):button('Xem trước nới giới hạn lên 42 phút','relax-preview')}${button('Giữ danh sách, quay lại cân nhắc','close')}</div>${state.locked.includes(2)?textButton('Quay lại lựa chọn để sửa khóa','nav-explore'):''}<p class="small" style="margin-top:20px">Số phút ở đây là dữ liệu kịch bản. Production phải lấy cái giá đã tính từ backend.</p>`);}
function duration(id) {const p=pOf(id);if(!p)return;showDialog('Thời gian ở lại · '+p.short,`<p>Chỉ đổi sau khi xem phần lịch bị ảnh hưởng.</p><form id="duration-form" data-form="duration" data-place="${id}" style="margin-top:24px"><label>Thời lượng (phút)<input name="minutes" type="number" min="15" max="240" step="15" value="${state.duration[id]||p.duration}" required></label><div class="row" style="margin-top:16px">${[30,60,90,150].map(n=>button(n+' phút','duration-preset-'+n,'soft small')).join('')}</div><p class="small" style="margin-top:20px">Giữ tập nơi, chỗ ở và nơi đã khóa. Đổi thời lượng sẽ cần tính lại giờ trong ngày.</p></form>`,`${button('Để sau','close')}<button type="submit" class="btn primary" form="duration-form">Xem trước thay đổi</button>`);}
function backups() {showDialog('Độ vững & phương án dự phòng',`<span class="eyebrow">Ngày ${state.day+1} · Điều cần chú ý</span><h3>Giờ ghé và đường đi chưa xác nhận</h3><p>Mock không chạy validator nên không gắn nhãn “Vững”. Production giải thích độ vững bằng dữ liệu của ngày hiện tại.</p><section class="receipt"><h3>Nếu mưa hoặc không thấy mây</h3><p>Có thể để dành điểm ngoài trời và giữ khoảng tự do. Chỉ thay lịch sau khi bạn chọn cách sửa.</p>${textButton('Xem trước phương án bớt Cầu Đất','backup-preview')}</section><section class="receipt"><h3>Nếu bị trễ</h3><p>Xem những điểm còn lại và giới hạn giờ kết thúc; không lặng lẽ bỏ nơi đã khóa.</p>${textButton('Xem cách điều chỉnh','late-adjust')}</section><p class="small" style="margin-top:20px">Production cần lấy backup từ danh sách có thật và kiểm tra khả thi trước khi áp dụng.</p>`);}
function optimize() {showDialog('Tối ưu quanh lựa chọn của bạn',`<span class="eyebrow">Giữ lựa chọn của bạn</span><h3>Chưa có kết quả kiểm chứng trong mock.</h3><p style="margin-top:14px">Production chỉ giữ đề xuất sau kiểm tra tất định và khi không kém lịch hiện tại.</p><div class="receipt"><h3>Phần được giữ</h3><p>Chỗ ở · nhịp đi · tập nơi · các nơi đã khóa.</p></div><div class="receipt"><h3>So sánh trước → sau</h3><p>Di chuyển, giờ ghé, độ vững và giá phải đọc từ lịch đã kiểm. Không dựng số cải thiện giả.</p></div>`,`${button('Giữ lịch hiện tại','close','primary')}`);}
function calendar() {showDialog('Xem trước Google Calendar',`<p>Chỉ ghi vào lịch riêng của TripGuardian sau khi bạn xác nhận. Không sửa các sự kiện khác.</p><div style="margin-top:22px">${state.days.flatMap((ids,d)=>ids.map((id,i)=>`<div class="calendar-row"><span class="mono">${dayDate(d)}<br>${i?'11:00':'05:30'}</span><div><b>${pOf(id).short}</b><small>Tạo mới · giờ minh họa · chưa ghi thật</small></div></div>`)).join('')}</div>${notice('Mock không kết nối tài khoản Google và không tạo sự kiện thật.','warn')}`,`${button('Để sau','close')}${button('Xác nhận bản xuất minh họa','calendar-apply','primary')}`);}
function deleteAccount(final=false) {showDialog(final?'Xác nhận xóa tài khoản':'Xóa tài khoản?',`<p>${final?'Đây là bước xác nhận thứ hai. Trong mock, chỉ xóa dữ liệu prototype trên trình duyệt này.':'Xóa hồ sơ, avatar, liên kết Calendar và thông báo. Các chuyến và số liệu phục vụ thống kê sẽ không còn gắn với bạn.'}</p>${final?'<label style="margin-top:22px">Gõ XÓA để xác nhận<input id="delete-confirm" autocomplete="off" placeholder="XÓA"></label>':''}`,`${button('Giữ tài khoản','close')}${button(final?'Xóa dữ liệu mock':'Tiếp tục','delete-'+(final?'apply':'second'),'danger',final?'disabled id="delete-submit"':'')}`);}
function chooseStay(i) {if(state.stay===i)return;if(state.stay!==null){showDialog('Đổi chỗ ở?',`<p>Bạn đang ở <b>${esc(STAYS[state.stay]?.name||'chỗ đã cung cấp')}</b>. Đổi sang <b>${esc(STAYS[i].name)}</b> thì mọi ngày bắt đầu và kết thúc ở chỗ mới; lịch được tính lại.</p><p class="small" style="margin-top:18px">Cả chuyến chỉ có một chỗ ở. Đây không phải thao tác đặt phòng.</p>`,`${button('Giữ chỗ cũ','close')}${button('Xác nhận đổi','apply-stay-'+i,'primary')}`);}else{remember();state.stay=i;state.diff='Đã chọn chỗ ở · đường đi cần tính lại';render();toast('Đã chọn '+STAYS[i].name);}}
function applyMutation(fn,message){remember();fn();state.diff=message;closeDialog();render();toast(message);}
const actions={
 close:closeDialog,summary,selected:selectedDialog,robustness:backups,conflicts:()=>conflicts(), 'physical-conflict':()=>conflicts(true),backups,optimize,calendar,
 'nav-inbox':()=>go('inbox'),'design-mobile':()=>showDialog('Phạm vi production',`<p>User Web production hiện tại dành cho desktop. Prototype này thiết kế đầy đủ luồng đó, trừ landing page; không mở rộng thêm ứng dụng điện thoại hoặc Admin.</p>`),
 reset:()=>{state=initial();closeDialog();location.hash='discover';render();toast('Đã đặt lại kịch bản mock');},google:()=>{state.guest=false;go('consent');},guest:()=>{state.guest=true;go('discover');},accept:()=>{state.guest=false;go('discover');},retry:()=>{state.scenario='normal';render();},
 'new-trip':()=>{state=Object.assign(initial(),{saved:state.saved,profile:state.profile,guest:state.guest,selected:[],locked:[],days:[[],[],[]],understood:false});go('understand');},resume:()=>go(state.variant===null?'understand':'overview'),
 'first-story':()=>{state.understood=true;state.question='pace';render();},'skip-pace':()=>{state.pace='Chưa rõ';state.question='dates';render();},'skip-date':()=>{state.date='';state.question='logistics';render();},'finish-questions':()=>{state.question='finished';render();},
 'to-selection':()=>{state.group='all';go('explore');},assistant:()=>{state.assistant=!state.assistant;render();},'why-not':()=>{state.assistantReply='Trong kịch bản này, Langbiang ở khu Lạc Dương, khác cụm Trại Mát bạn đang cân nhắc. Mock chưa kiểm tra điều kiện và quãng đường, nên không kết luận rằng nơi này không hợp bạn.';render();},
 undo:()=>{if(!state.undo)return toast('Chưa có thay đổi để hoàn tác');const u=state.undo;Object.assign(state,u);state.undo=null;state.diff='Đã hoàn tác thay đổi';closeDialog();render();toast('Đã hoàn tác');},
 'match-import':()=>{const b=$('#match-import');if(b){b.textContent='Đã xác nhận';b.disabled=true;}state.importMatched=true;save();},'keep-import':()=>toast('Mục chưa khớp được giữ là chưa xác minh, chưa vào lịch'), 'remove-import':()=>{const items=$$('.import-item');items[2]?.remove();toast('Đã bỏ mục chưa xác minh');},
 'prefer-coffee':()=>{state.prefs=['Cà phê','Thiên nhiên'];toast('Đã ghi ưu tiên cà phê của chuyến này');save();},'prefer-nature':()=>{state.prefs=['Thiên nhiên','Cà phê'];toast('Đã ghi ưu tiên thiên nhiên của chuyến này');save();},
 'to-choices':()=>{state.variant=null;go('choices');},'to-overview':()=>{if(state.variant===null)return;go('overview');},'confirm-plan':()=>{if(['conflict','unavailable'].includes(state.scenario))return;showDialog('Chốt kế hoạch này?',`<p>Bạn đang chọn phương án <b>${variants()[state.variant??0].name}</b>, với ${state.days.flat().length} nơi trong ${state.days.length} ngày.</p>${notice('Trong mock, đây là mô phỏng chốt kế hoạch. Giờ, chi phí và khả thi chưa được backend kiểm tra.','warn')}`,`${button('Xem lại lịch','close')}${button('Chốt trong prototype','apply-confirm','primary')}`);},'apply-confirm':()=>{state.confirmed=true;go('done');},
 'keep-all':()=>showDialog('Giữ tất cả · xem lịch gốc',`<p>${state.selected.length} nơi trong 3 ngày. Production chỉ cho chọn nếu lịch gốc vượt qua validation.</p>${notice('Kịch bản quá tải này chưa có lịch gốc hợp lệ. Nút chọn Giữ tất cả bị khóa.','danger','warn')}`,`${button('Quay lại cân nhắc','close')}${button('Chọn Giữ tất cả','noop','primary','disabled')}`),
 maps:()=>{const ps=(state.screen==='overview'?state.days.flat():state.days[state.day]).map(pOf).filter(Boolean);if(!ps.length)return;const first=ps[0],last=ps[ps.length-1];const url='https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(first.lat+','+first.lng)+'&destination='+encodeURIComponent(last.lat+','+last.lng)+'&travelmode=driving';window.open(url,'_blank','noopener');},
 'conflict-save-later':()=>{if(state.locked.includes(2))return toast('Cầu Đất đã khóa. Mở khóa ở Lựa chọn trước khi để dành.');return applyMutation(()=>{state.selected=state.selected.filter(id=>id!==2);state.days=state.days.map(d=>d.filter(id=>id!==2));state.scenario='normal';},'Đã để dành Cầu Đất · giữ các nơi còn lại');},
 'relax-preview':()=>showDialog('Nới lên 42 phút / chặng?',`<p>Giới hạn hiện tại: <b>30 phút</b>. Giới hạn mới: <b>42 phút</b>.</p><div class="receipt"><b>Cái giá của kịch bản</b><p>Chấp nhận thêm 12 phút cho chặng xa nhất. Chưa thay đổi giờ mở cửa hay giới hạn vật lý.</p></div>`,`${button('Giữ 30 phút','close')}${button('Xác nhận nới giới hạn','apply-relax','primary')}`),
 'apply-relax':()=>applyMutation(()=>{state.scenario='normal';state.maxLeg=42;},'Bạn đã nới giới hạn mỗi chặng lên 42 phút'),
 'clear-stay':()=>showDialog('Bỏ chỗ ở đã chọn?',`<p>Không có chỗ ở thì đường đi mỗi sáng và tối chưa tính đủ. Chỗ ở không bị hủy booking ngoài đời.</p>`,`${button('Giữ chỗ ở','close')}${button('Xác nhận bỏ','apply-clear-stay','primary')}`),'apply-clear-stay':()=>applyMutation(()=>state.stay=null,'Đã bỏ chỗ ở · đường đi chưa tính đủ'),
 'backup-preview':()=>showDialog('Xem trước phương án dự phòng',`<p>Để dành <b>Săn mây Cầu Đất</b>; giữ khoảng tự do ở Ngày 1. Các nơi đã khóa vẫn giữ.</p>${notice('Mock chưa kiểm tra điều kiện thay thế. Trong production, chỉ apply preview đã qua validation.','warn')}`,`${button('Giữ lịch hiện tại','close')}${button(state.locked.includes(2)?'Nơi đã khóa, không thể bỏ':'Áp dụng trong kịch bản','apply-backup','primary',state.locked.includes(2)?'disabled':'')}`),
 'apply-backup':()=>{if(state.locked.includes(2))return toast('Giữ Cầu Đất vì bạn đã khóa nơi này.');return applyMutation(()=>{state.days=state.days.map(d=>d.filter(id=>id!==2));state.selected=state.selected.filter(id=>id!==2);},'Đã để dành Cầu Đất · chỉ đổi ngày bị ảnh hưởng');},
 'late-adjust':()=>showDialog('Phần còn lại hơi chật',`<p>Bạn chọn cách sửa, mình không tự bỏ nơi.</p><div class="stack" style="margin-top:22px">${button('Giữ nơi đã khóa, xem phần có thể để dành','backup-preview','soft')}${button('Xem lại thời lượng ghé','duration-0')}${button('Giữ lịch, tự cân nhắc','close')}</div>`),
 'other-place':()=>showDialog('Bạn đang ở đâu?',`<p>Không cần GPS. Chọn đúng tên nơi để check-in.</p><div class="stack" style="margin-top:20px">${PLACES.slice(0,3).map(p=>button(p.name,'checkin-'+p.id)).join('')}</div>`),
 nearby:()=>showDialog('Gần đây / nơi tương tự',`<p>Gợi ý phải vừa quãng đường và khoảng thời gian trước điểm sau.</p>${rowPlace(PLACES[5])}<small>Danh sách này minh họa layout. Chưa đủ kiểm tra khả thi để thêm tự động.</small>`),
 'enable-notifications':()=>{state.notifies.enabled=!state.notifies.enabled;render();toast(state.notifies.enabled?'Đã bật trong mock · không xin quyền browser thật':'Đã tắt trong mock');},'calendar-apply':()=>{state.calendar=true;closeDialog();render();toast('Đã xác nhận bản xuất minh họa · không ghi Google Calendar thật');},
 'disconnect-calendar':()=>showDialog('Ngắt Google Calendar?',`<p>Ngắt liên kết và dừng các cập nhật sau này. Chỉ thay đổi trạng thái trong mock.</p>`,`${button('Giữ kết nối','close')}${button('Ngắt kết nối','apply-disconnect','primary')}`),'apply-disconnect':()=>{state.calendar=false;closeDialog();render();toast('Đã ngắt trong mock');},
 'delete-account':()=>deleteAccount(),'delete-second':()=>deleteAccount(true),'delete-apply':()=>{if($('#delete-confirm')?.value!=='XÓA')return;state=initial();go('login');toast('Đã xóa dữ liệu prototype · tài khoản thật không thay đổi');},
 'end-guest':()=>showDialog('Kết thúc phiên khách?',`<p>Xóa dữ liệu chuyến khách trong prototype này.</p>`,`${button('Tiếp tục dùng','close')}${button('Kết thúc phiên mock','apply-end-guest','danger')}`),'apply-end-guest':()=>{state=initial();go('login');},
 signout:()=>go('login'),'edit-confirmed':()=>showDialog('Sửa lại kế hoạch?',`<p>Chuyến quay về bước Lựa chọn, giữ các nơi đã chọn. Thay đổi lịch Google cần xem trước và xác nhận lại.</p>`,`${button('Giữ kế hoạch','close')}${button('Sửa lại','apply-edit-confirmed','primary')}`),'apply-edit-confirmed':()=>{state.confirmed=false;go('explore');},
 'hide-trip':()=>showDialog('Ẩn khỏi danh sách trình duyệt?',`<p>Không xóa chuyến trên máy chủ. Chỉ ẩn trên trình duyệt này.</p>`,`${button('Giữ lại','close')}${button('Ẩn chuyến minh họa','apply-hide-trip','primary')}`),'apply-hide-trip':()=>{state.emptyTrips=true;closeDialog();render();},
 report:()=>showDialog('Báo thông tin sai',`<p>Báo cáo chỉ gửi vào hàng đợi kiểm tra, không sửa dữ liệu địa điểm.</p><form id="report-form" data-form="report" class="stack" style="margin-top:20px"><label>Thông tin bạn muốn báo<select name="field"><option>Giờ mở cửa</option><option>Giá</option><option>Đường đi</option><option>Địa điểm trùng / sai tên</option></select></label><label>Mô tả ngắn<textarea name="note" required placeholder="Bạn thấy thông tin nào chưa đúng?"></textarea></label></form>`,`${button('Để sau','close')}<button type="submit" class="btn primary" form="report-form">Gửi trong mock</button>`),
 evidence:()=>showDialog('Nhận định cách bằng chứng một chạm',`<span class="eyebrow">Cấu trúc hiển thị</span><h3>Trải nghiệm: nội dung nhận định</h3><div class="receipt"><p><b>Khi có signal:</b> xu hướng + bối cảnh + cỡ mẫu thật, không suy từ tổng số review.</p><p style="margin-top:12px"><b>Khi mở bằng chứng:</b> đoạn review nguồn, ngày, link gốc; clip phát đúng timestamp; chưa có nguồn thì ghi “Chưa có thông tin”.</p></div><div class="receipt"><p><b>Fact xung đột:</b> giữ cả hai giá trị và nguồn. Không chọn một giá trị để tạo cảm giác chắc chắn.</p></div>`),
 avatar:()=>showDialog('Đổi avatar',`<p>Chọn ảnh để xem trước. Mock không upload hoặc lưu ảnh cá nhân.</p><label class="btn" style="margin-top:20px;cursor:pointer">${icon('clip')} Chọn ảnh<input id="avatar-image" type="file" accept="image/*" hidden></label><div id="avatar-preview" style="margin-top:22px"></div>`,button('Đóng','close')),
 'sample-primary':()=>toast('Một hành động chính cho mỗi quyết định'),'sample-secondary':()=>toast('Thao tác phụ vẫn nhìn thấy rõ'),'sample-save':()=>toast('Lưu tách khỏi lựa chọn chuyến'),noop:()=>{}
};
function handleAction(action) {
 if(actions[action])return actions[action]();
 if(action.startsWith('nav-'))return go(action.slice(4));
 if(action.startsWith('scenario-')){const [screen,scenario]=action.slice(9).split('-');state.screen=screen;state.scenario=scenario;if(scenario==='overload'&&screen==='choices')state.selected=PLACES.map(p=>p.id);state.variant=null;location.hash=screen;render();window.scrollTo(0,0);return;}
 const [prefix,id]=action.split('-');
 if(prefix==='detail')return openDetail(id);
 if(prefix==='signal'){const p=pOf(id),f=p.signals.find(x=>x.id===action.split('-').slice(2).join('-'));if(!f)return;return showDialog(f.label+' · '+p.short,`<span class="eyebrow">Metadata bằng chứng có thật</span><h3>${f.n} lượt nhắc trong serving</h3><p>Có bằng chứng trong dữ liệu kiểm tra ngày ${p.asOf||'chưa có ngày'}.</p><div class="receipt"><h3>Số bản ghi theo nguồn</h3>${Object.entries(f.bySource||{}).map(([k,v])=>`<div class="summary-field"><span>${esc({gmaps_review:'Đánh giá Google Maps',gmaps_photo:'Ảnh Google Maps',tiktok_caption:'Caption TikTok',tiktok_frame:'Frame TikTok',tiktok_comment:'Bình luận TikTok'}[k]||k)}</span><b>${v}</b></div>`).join('')}</div><p class="small" style="margin-top:20px">Không coi số lượt nhắc là tỷ lệ tất cả người ghé. Mock chỉ lấy metadata, không chép review hoặc tên người thật. Production mở trích đoạn / clip nguồn tại từng nhận định.</p><a class="text" href="${p.mapsUrl}" target="_blank" rel="noopener">Xem địa điểm trên Google Maps ${icon('external')}</a>`,button('Về chi tiết','detail-'+p.id));}

 if(prefix==='save'){const n=Number(id);state.saved=state.saved.includes(n)?state.saved.filter(x=>x!==n):[...state.saved,n];save();refreshKeepingDialog();return;}
 if(prefix==='select'||prefix==='remove'){
  const n=Number(id),selected=state.selected.includes(n);if(selected&&state.locked.includes(n))return toast('Bỏ khóa trước khi bỏ nơi này');remember();if(selected){state.selected=state.selected.filter(x=>x!==n);state.days=state.days.map(d=>d.filter(x=>x!==n));state.diff='−1 nơi · lịch cần kiểm tra lại';}else{state.selected.push(n);state.diff='+1 nơi · lịch cần kiểm tra lại';}refreshKeepingDialog();return;
 }
 if(prefix==='lock'){const n=Number(id);state.locked=state.locked.includes(n)?state.locked.filter(x=>x!==n):[...state.locked,n];if(state.locked.includes(n)&&!state.selected.includes(n))state.selected.push(n);refreshKeepingDialog();toast(state.locked.includes(n)?'Đã khóa '+pOf(n).short:'Đã bỏ khóa '+pOf(n).short);return;}
 if(prefix==='stay')return chooseStay(Number(id));
 if(action.startsWith('apply-stay-'))return applyMutation(()=>state.stay=Number(action.slice(11)),'Đã đổi chỗ ở · các ngày cần tính lại đường đi');
 if(prefix==='variant'){const v=variants()[Number(id)];if(v?.unavailable)return;state.variant=v.id;const count=state.days.length;state.days=Array.from({length:count},(_,d)=>d===count-1?v.keep.slice(d*2):v.keep.slice(d*2,d*2+2));render();toast('Đang chọn '+v.name);return;}
 if(action.startsWith('preview-variant-')){const v=variants()[Number(action.slice(16))];return showDialog(v.name,`<p>${v.desc}</p>${Array.from({length:state.days.length},(_,d)=>d===state.days.length-1?v.keep.slice(d*2):v.keep.slice(d*2,d*2+2)).map((ids,d)=>`<div class="receipt"><b>Ngày ${d+1}</b><p>${ids.map(id=>pOf(id).short).join(' → ')}</p></div>`).join('')}`,button('Quay lại so sánh','close'));}
 if(prefix==='duration' && id!=='preset')return duration(Number(id));
 if(action.startsWith('duration-preset-')){const input=$('input[name=minutes]');if(input)input.value=action.slice(16);return;}
 if(action.startsWith('apply-duration-')){const parts=action.split('-'),n=Number(parts[2]),minutes=Number(parts[3]);return applyMutation(()=>state.duration[n]=minutes,'Đã đổi thời lượng '+pOf(n).short+' · cần tính lại giờ');}
 if(action.startsWith('apply-move-')){const parts=action.split('-'),n=Number(parts[2]),d=Number(parts[3]);return applyMutation(()=>{state.days=state.days.map(x=>x.filter(id=>id!==n));state.days[d].push(n);},'Đã chuyển '+pOf(n).short+' sang Ngày '+(d+1));}
 if(prefix==='checkin'){state.checkins[Number(id)]=true;state.skipped[Number(id)]=false;closeDialog();render();toast('Đã ghi nhận đến nơi trong mock');return;}
 if(prefix==='here'){return showDialog('Ở đây · '+pOf(id).short,`<p>Không suy hoạt động từ loại nơi. Khi có dữ liệu, production hiển thị nội dung “Chơi gì ở đây”, lưu ý và bằng chứng.</p>${rowPlace(pOf(id))}${button('Xem nơi gần đây','nearby','soft')}`);}
 if(prefix==='skip'){return showDialog('Bỏ qua · '+pOf(id).short,`<p>Lý do không bắt buộc. Bỏ qua không có nghĩa là bạn không thích nơi này.</p><div class="row" style="margin-top:20px">${['Đông quá','Mệt rồi','Thời tiết','Không hợp','Không nói'].map(l=>button(l,'apply-skip-'+id+'-'+encodeURIComponent(l))).join('')}</div>`);}
 if(action.startsWith('apply-skip-')){const n=Number(action.split('-')[2]);state.skipped[n]=true;state.checkins[n]=false;closeDialog();render();toast('Đã bỏ qua · lịch kế hoạch vẫn còn');return;}
 if(prefix==='unskip'){delete state.skipped[id];render();return;}
 if(prefix==='rate'){const bits=action.split('-'),n=Number(bits[1]),value=action.includes('--1')?-1:1;state.ratings[n]=state.ratings[n]===value?null:value;render();toast('Đã ghi phản hồi của bạn');return;}
}
function refreshKeepingDialog(){const kind=dialogKind,p=modalPlace,open=$('#dialog').open;render();if(open&&kind==='detail'&&p!==null){$('#dialog .dialog-content').innerHTML=detailContent(pOf(p),true);}else if(open&&kind==='selected')selectedDialog();}
document.addEventListener('click',e=>{
 const el=e.target.closest('button,a,label');if(!el||el.disabled)return;
 if(el.dataset.action){handleAction(el.dataset.action);return;}
 if(el.dataset.nav){go(el.dataset.nav);return;}
 if(el.dataset.detail){openDetail(el.dataset.detail);return;}
 if(el.dataset.save){handleAction('save-'+el.dataset.save);return;}
 if(el.dataset.pace){state.pace=el.dataset.pace;state.question='dates';render();toast('Đã ghi nhịp '+state.pace.toLowerCase());return;}
 if(el.dataset.group){state.group=el.dataset.group;render();return;}
 if(el.dataset.catalog){const g=el.dataset.catalog;state.group=g==='lodging'?'all':g;if(g==='lodging')go('lodging');else if(state.screen==='lodging')go('explore');else render();return;}
 if(el.dataset.day){state.day=Number(el.dataset.day);if(el.dataset.openDay)go('day');else render();return;}
 if(el.dataset.detailTab){state.detailTab=el.dataset.detailTab;if($('#dialog').open&&modalPlace!==null){$('#dialog .dialog-content').innerHTML=detailContent(pOf(modalPlace),true);}else render();return;}
 if(el.dataset.image){showDialog('Hình ảnh · Google Maps',`<img class="image-view" src="${el.dataset.image}" alt="Ảnh địa điểm từ catalog">`,button('Về chi tiết','detail-'+state.detailId),'', 'image');return;}
 if(el.dataset.startChip){const input=$('#start-text');if(input)input.value+=(input.value?', ':'')+el.dataset.startChip;return;}
 if(el.dataset.theme){state.story='Mình muốn '+({2:'săn mây buổi sáng rồi cà phê',0:'ngồi cà phê, sống chậm',1:'chiều muộn bên hồ'}[el.dataset.theme]);state.understood=true;state.question='pace';go('understand');return;}
 if(el.dataset.importIntent){$$('[data-import-intent]').forEach(b=>b.setAttribute('aria-pressed',String(b===el)));state.importIntent=el.dataset.importIntent;save();return;}
 if(el.dataset.score){const [key,n]=el.dataset.score.split(':');state.feedback[key]=Number(n);const group=el.closest('[role=radiogroup]');$$('[role=radio]',group).forEach(b=>b.setAttribute('aria-checked',String(b===el)));save();return;}
 if(el.dataset.more){state.feedback.more=el.dataset.more;$$('[data-more]').forEach(b=>b.setAttribute('aria-pressed',String(b===el)));save();return;}
 if(el.dataset.switch){state.notifies[el.dataset.switch]=!state.notifies[el.dataset.switch];el.setAttribute('aria-checked',String(state.notifies[el.dataset.switch]));save();return;}
 if(el.dataset.notification){state.read.push(Number(el.dataset.notification));handleAction(el.dataset.notificationAction);return;}
});
document.addEventListener('change',e=>{const el=e.target;
 if(el.id==='screen-picker')go(el.value);
 if(el.id==='scenario-picker'){state.scenario=el.value;if(el.value==='overload'&&state.screen==='choices'){state.selected=PLACES.map(p=>p.id);state.variant=null;}render();}
 if(el.id==='consent-check')$('#consent-submit').disabled=!el.checked;
 if(el.dataset.compare){const n=Number(el.dataset.compare);if(el.checked&&state.compare.length>=3){el.checked=false;toast('So sánh tối đa 3 nơi');return;}state.compare=el.checked?[...state.compare,n]:state.compare.filter(id=>id!==n);render();}
 if(el.dataset.move){const n=Number(el.dataset.move),day=Number(el.value);if(state.locked.includes(n))return;showDialog('Chuyển sang Ngày '+(day+1)+'?',`<p>Chuyển <b>${pOf(n).short}</b> sang Ngày ${day+1}. Ngày cũ và ngày mới cần tính lại giờ, chặng đi và kiểm tra giới hạn.</p>${notice('Trong mock, chỉ thay đổi tập nơi theo ngày. Không kết luận giờ mới đã khả thi.','warn')}`,`${button('Giữ ngày cũ','close')}${button('Áp dụng thay đổi đã xem','apply-move-'+n+'-'+day,'primary')}`);el.value=state.day;}
 if(el.id==='chat-image'&&el.files[0]){state.messages.push('Ảnh đã đính kèm: '+el.files[0].name+' · mock không đọc nội dung ảnh');render();toast('Đã mô phỏng đính kèm ảnh');}
 if(el.id==='avatar-image'&&el.files[0]){const url=URL.createObjectURL(el.files[0]);$('#avatar-preview').innerHTML=`<img src="${url}" alt="Avatar xem trước" style="width:120px;height:120px;border-radius:50%">`;$('#avatar-preview img').onload=()=>URL.revokeObjectURL(url);}
});
document.addEventListener('input',e=>{if(e.target.id==='delete-confirm')$('#delete-submit').disabled=e.target.value!=='XÓA';});
document.addEventListener('submit',e=>{const f=e.target;if(!f.dataset.form)return;e.preventDefault();const data=new FormData(f),type=f.dataset.form;
 if(type==='start'){state.story=$('#start-text').value.trim()||'Mình chưa biết đi đâu, gợi ý giúp mình.';state.understood=true;state.question='pace';state.messages=[];go('understand');}
 if(type==='chat'){const value=$('#chat-text').value.trim();if(!value)return;if(!state.understood){state.story=value;state.understood=true;}else state.messages.push(value);render();const log=$('#chat-log');if(log)log.scrollTop=log.scrollHeight;}
 if(type==='dates'){state.date=data.get('date');state.question='logistics';render();}
 if(type==='logistics'){state.origin=data.get('origin');state.transport=data.get('transport');state.bookedText=data.get('stay');state.question='finished';render();toast('Đã ghi thông tin bạn cung cấp');}
 if(type==='summary'){remember();state.date=data.get('date');state.people=Number(data.get('people'));state.pace=data.get('pace');for(const key of ['companions','mobility','origin','transport','arrival','departure','dayEnd','bookedText'])state[key]=data.get(key)||null;for(const key of ['budget','maxLeg'])state[key]=data.get(key)===''?null:Number(data.get(key));state.avoidSteep=data.get('avoidSteep')==='unknown'?null:data.get('avoidSteep')==='true';state.prefs=data.getAll('prefs');const n=Number(data.get('days'));if(n<state.days.length){const tail=state.days.slice(n).flat();state.days=state.days.slice(0,n);state.days[n-1].push(...tail);}else while(state.days.length<n)state.days.push([]);state.diff='Đã sửa nhu cầu · lịch cần kiểm tra lại';closeDialog();render();toast('Đã cập nhật tóm tắt chuyến đi');}
 if(type==='assistant'){state.assistantReply='Mình đã giữ yêu cầu “'+$('#assistant-text').value.trim()+'” trong ghi chú của kịch bản. Muốn đổi các nơi, bạn chọn trực tiếp trên danh sách; mock chưa gọi Decision Agent.';render();}
 if(type==='profile'){state.profile={name:data.get('name'),origin:data.get('origin'),mobility:data.get('mobility'),companions:data.get('companions')};render();toast('Đã lưu hồ sơ trong prototype');}
 if(type==='feedback'){state.feedback.note=data.get('note');state.feedbackSent=true;render();}
 if(type==='stay-search'){const name=String(data.get('query')).trim(),i=STAYS.findIndex(s=>s.name.toLowerCase()===name.toLowerCase());if(i>=0)chooseStay(i);else showDialog('Chưa khớp được chỗ ở',`<p>“${esc(name)}” chưa có ứng viên được xác minh trong mock. Không tự chọn tên gần giống.</p>`,button('Tiếp tục tìm','close'));}
 if(type==='duration'){const id=Number(f.dataset.place),minutes=Number(data.get('minutes'));showDialog('Xem trước đổi thời lượng',`<p><b>${pOf(id).short}</b>: ${state.duration[id]||pOf(id).duration} phút → <b>${minutes} phút</b>.</p><div class="receipt"><b>Phần bị ảnh hưởng</b><p>Giờ rời nơi, các điểm phía sau và tổng giờ trong Ngày ${state.days.findIndex(d=>d.includes(id))+1}. Tập nơi, chỗ ở và nơi khóa được giữ.</p></div>${notice('Mock không tính lại đường đi hoặc validation. Khi dùng thật, chỉ áp dụng thay đổi đã được kiểm tra.','warn')}`,`${button('Để sau','close')}${button('Áp dụng trong kịch bản','apply-duration-'+id+'-'+minutes,'primary')}`);}
 if(type==='report'){closeDialog();toast('Đã mô phỏng gửi báo cáo · không sửa dữ liệu địa điểm');}
});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&state.screen==='explore'&&!$('#dialog').open){e.preventDefault();state.assistant=true;render();$('#assistant-text')?.focus();}if(e.key==='Escape'&&state.assistant){state.assistant=false;render();}const el=e.target;if(el.getAttribute('role')==='tab'&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=$$('[role=tab]',el.closest('[role=tablist]'));const i=tabs.indexOf(el),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;const key=tabs[next].dataset.day?'day':tabs[next].dataset.group?'group':tabs[next].dataset.catalog?'catalog':'detailTab',value=tabs[next].dataset[key];tabs[next].click();$(`[data-${key==='detailTab'?'detail-tab':key}="${value}"]`)?.focus();}if(el.getAttribute('role')==='radio'&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const group=el.closest('[role=radiogroup]'),items=$$('[role=radio]',group),i=items.indexOf(el),next=e.key==='Home'?0:e.key==='End'?items.length-1:(i+(e.key==='ArrowRight'?1:-1)+items.length)%items.length;items[next].click();items[next].focus();}});
window.addEventListener('resize',updateMaps);
window.addEventListener('hashchange',()=>{const s=location.hash.slice(1);if(SCREEN_NAMES[s]&&state.screen!==s){closeDialog();state.screen=s;state.scenario='normal';state.assistant=false;render();window.scrollTo(0,0);}});
const route=location.hash.slice(1);if(SCREEN_NAMES[route])state.screen=route;
render();
